// ============================================================================
// Statusline — 两行紧凑状态条，位于发送栏正上方（借鉴 DSH SessionStatusBar）：
//   第 1 行  上下文占用环(≥90% 警告色) + 「xxxK/1M」 + 当前模型 + 思考强度
//   第 2 行  tokens/s + 缓存命中率(W263) + step 数
// 数据源：GET /api/status 轮询（兜底）+ SSE status 事件增量字段
//   （SSE status 的 statusline 快照是嵌套对象，fromSse 里拍平后合并）。
// W227：模型/推理档位改为可点击按钮 → 紧凑下拉面板快速切换（POST /api/config），
//   409（轮次进行中）→ 提示并挂起，SSE done 后自动重试一次；400/500 → 内联报错。
// ============================================================================
import { api, ApiError } from './api';
import { el, fmtCompact, need } from './utils/dom';
import { popOverlay, pushOverlay, type OverlayHandle } from './utils/overlays';
import type {
  ConfigInfo,
  ConfigPatch,
  ModelInfo,
  StatusPayload,
  StatusSnapshot,
  UsageSnapshot,
} from './types';

const POLL_MS = 2000;
const RING_R = 5.2;
const RING_C = 2 * Math.PI * RING_R;
/** context ring turns warning color at/above this ratio */
const WARN_RATIO = 0.9;

/** W262：没有 provider 字段的模型（静态兜底目录 / 旧数据）归入的树状分组。 */
const OTHER_GROUP = '其他';

const EFFORT_OPTIONS: readonly { value: string | null; label: string }[] = [
  { value: null, label: '标准（清除）' },
  { value: 'low', label: 'low' },
  { value: 'high', label: 'high' },
  { value: 'max', label: 'max' },
];

type SwitchKind = 'model' | 'effort';

export class Statusline {
  private snapshot: StatusSnapshot = {};
  private timer: number | null = null;
  private el: HTMLElement;
  private ring: HTMLElement;
  private ringProg: SVGCircleElement;
  private ctxEl: HTMLElement;
  private modelEl: HTMLElement;
  private effortEl: HTMLElement;
  private tpsEl: HTMLElement;
  /** W263: cache-hit-ratio cell (last stream + cumulative in the title). */
  private cacheEl: HTMLElement;
  private stepsEl: HTMLElement;
  private hintEl: HTMLElement;

  // ---- 快速切换（W227） ----
  private popup: HTMLElement | null = null;
  private popupKind: SwitchKind | null = null;
  /** 任务 3：弹层在全局层级栈中的句柄（Esc 只关栈顶一层）。 */
  private popupOverlay: OverlayHandle | null = null;
  private pendingPatch: ConfigPatch | null = null;
  private staleMsg = '';
  private note = '';
  private noteTimer: number | null = null;

  constructor() {
    this.el = need<HTMLElement>('#statusline');
    this.ring = need<HTMLElement>('.sl-ring', this.el);
    this.ringProg = need<SVGCircleElement>('.sl-ring-prog', this.el);
    this.ctxEl = need<HTMLElement>('#slCtx', this.el);
    this.modelEl = need<HTMLElement>('#slModel', this.el);
    this.effortEl = need<HTMLElement>('#slEffort', this.el);
    this.tpsEl = need<HTMLElement>('#slTps', this.el);
    this.cacheEl = need<HTMLElement>('#slCache', this.el);
    this.stepsEl = need<HTMLElement>('#slSteps', this.el);
    this.hintEl = need<HTMLElement>('#slHint', this.el);
    this.ringProg.style.strokeDasharray = String(RING_C);
    this.el.title = '上下文占用 · 模型 · 思考强度 · 吞吐 · 缓存命中（GET /api/status + SSE 增量）';

    // W227：模型/档位点击快速切换
    this.modelEl.addEventListener('click', () => this.togglePopup('model'));
    this.effortEl.addEventListener('click', () => this.togglePopup('effort'));
    // Esc 关闭统一由 utils/overlays 层级栈处理（任务 3：唯一 document Esc 监听）
    document.addEventListener('click', (e) => {
      if (!this.popup) return;
      const t = e.target as Node;
      if (this.popup.contains(t)) return;
      if (this.modelEl.contains(t) || this.effortEl.contains(t)) return;
      this.closePopup();
    });
  }

  /** Begin polling /api/status. */
  start(): void {
    this.poll();
    this.timer = window.setInterval(() => this.poll(), POLL_MS);
  }

  stop(): void {
    if (this.timer !== null) {
      window.clearInterval(this.timer);
      this.timer = null;
    }
  }

  /**
   * Merge incremental fields from an SSE status payload.
   * W263: the backend nests the snapshot ({"phase":..,"statusline":{..}}), so
   * the nested snapshot is flattened first; flat fields (older/newer shapes)
   * still win when present.
   */
  fromSse(p: StatusPayload): void {
    const flat = pickStatusFields({ ...(p.statusline ?? {}), ...p });
    if (Object.keys(flat).length > 0) {
      this.snapshot = { ...this.snapshot, ...flat };
      this.render();
    }
  }

  /** Merge any partial snapshot (e.g. health model / POST /api/config 响应). */
  merge(partial: StatusSnapshot): void {
    this.snapshot = { ...this.snapshot, ...partial };
    this.render();
  }

  /** SSE done 事件钩子：存在 409 挂起的快速切换补丁时自动重试一次。 */
  onSseDone(): void {
    if (!this.pendingPatch) return;
    const patch = this.pendingPatch;
    this.pendingPatch = null;
    this.setNote('本轮已结束，正在应用切换…', 0);
    void api
      .saveConfig(patch)
      .then((d) => {
        this.merge({ model: d.model, reasoning_effort: d.reasoning_effort });
        this.setNote('已切换', 5000);
        window.dispatchEvent(new Event('studio:config-saved'));
      })
      .catch((err: unknown) => {
        this.setNote('切换失败：' + (err instanceof Error ? err.message : String(err)), 6000);
      });
  }

  // ---- 快速切换面板 ---------------------------------------------------------

  private togglePopup(kind: SwitchKind): void {
    if (this.popup && this.popupKind === kind) {
      this.closePopup();
      return;
    }
    void this.openPopup(kind);
  }

  private closePopup(): void {
    if (this.popupOverlay) {
      popOverlay(this.popupOverlay);
      this.popupOverlay = null;
    }
    if (this.popup) {
      this.popup.remove();
      this.popup = null;
      this.popupKind = null;
    }
  }

  private async openPopup(kind: SwitchKind): Promise<void> {
    this.closePopup();
    this.popupKind = kind;
    const popup = el('div', 'sl-popup');
    popup.setAttribute('role', 'menu');
    this.popup = popup;
    this.el.appendChild(popup);
    this.popupOverlay = pushOverlay(() => this.closePopup());

    popup.appendChild(el('div', 'sl-popup-title', kind === 'model' ? '切换模型' : '切换推理档位'));
    const body = el('div', 'sl-popup-body');
    popup.appendChild(body);
    body.appendChild(el('div', 'sl-popup-loading', '加载清单中…'));

    let cfg: ConfigInfo;
    try {
      cfg = await api.config();
    } catch (err) {
      if (this.popup !== popup) return;
      body.replaceChildren(
        el('div', 'sl-popup-error', '无法读取 /api/config：' + (err instanceof Error ? err.message : String(err))),
      );
      return;
    }
    if (this.popup !== popup) return; // 期间被关闭/切换

    // 铁律 1：整份清单先离屏构建，就绪后单次替换——「加载清单中…」保持可见到最后一刻。
    const off = document.createElement('div');

    if (kind === 'effort') {
      const options = [...EFFORT_OPTIONS];
      const cur = cfg.reasoning_effort ?? '';
      if (cur && !options.some((o) => o.value === cur)) {
        options.push({ value: cur, label: cur + '（当前）' });
      }
      for (const o of options) {
        off.appendChild(this.optButton(o.label, o.value ?? '', cur, () => this.apply({ reasoning_effort: o.value })));
      }
      body.replaceChildren(...off.childNodes);
      return;
    }

    // ---- model：按提供商分组的树状清单（W262） ----
    const models = Array.isArray(cfg.available?.models) ? cfg.available.models : [];
    const cur = cfg.model ?? this.snapshot.model ?? '';
    if (!models.length) {
      // 清单缺失 → 内联文本输入降级
      const row = el('div', 'sl-popup-textrow');
      const input = el('input', 'sl-popup-input') as HTMLInputElement;
      input.placeholder = '模型 id（后端未提供可选清单）';
      input.value = cur;
      row.appendChild(input);
      const applyBtn = el('button', 'btn btn-accent btn-mini', '应用') as HTMLButtonElement;
      applyBtn.addEventListener('click', () => {
        const v = input.value.trim();
        if (v !== '' && v !== cur) void this.apply({ model: v });
      });
      row.appendChild(applyBtn);
      off.appendChild(row);
      off.appendChild(el('div', 'sl-popup-note', '后端未返回 available.models，手动输入'));
      body.replaceChildren(...off.childNodes);
      return;
    }
    const known = models.some((m) => m.id === cur);
    if (cur && !known) {
      // 当前模型不在清单里（自定义端点）→ 置顶一行，仍可点回
      off.appendChild(this.optButton(cur + '（当前）', cur, cur, () => this.apply({ model: cur })));
      const sep = el('div', 'sl-popup-sep');
      sep.textContent = '候选模型';
      off.appendChild(sep);
    }
    // 树状一级 = provider 显示名（后端已保证模型名未定义时取 id）；
    // 缺 provider 字段的记录（静态兜底目录 / 旧数据）归入「其他」组。
    const groups = new Map<string, ModelInfo[]>();
    for (const m of models) {
      const key = (m.provider ?? '').trim() || OTHER_GROUP;
      const list = groups.get(key);
      if (list) list.push(m);
      else groups.set(key, [m]);
    }
    for (const [provider, list] of groups) {
      off.appendChild(this.groupRow(provider));
      for (const m of list) {
        off.appendChild(
          this.optButton(m.name || m.id, m.id, cur, () => this.apply({ model: m.id }), true),
        );
      }
    }
    body.replaceChildren(...off.childNodes);
  }

  /** W262：树状分组标题行 —— 提供商显示名，不可点击（无 button/无监听）。 */
  private groupRow(provider: string): HTMLElement {
    const row = el('div', 'sl-group');
    row.appendChild(el('span', 'sl-group-name', provider));
    return row;
  }

  /** 模型/档位一行；`sub=true` = 树状缩进一级（provider 组下的模型行）。 */
  private optButton(
    label: string,
    value: string,
    current: string,
    onPick: () => void,
    sub = false,
  ): HTMLElement {
    const cls =
      'sl-opt' +
      (sub ? ' sub' : '') +
      (value !== '' && value === current ? ' current' : '');
    const b = el('button', cls) as HTMLButtonElement;
    b.appendChild(el('span', 'sl-opt-name', label));
    if (value !== '') b.appendChild(el('span', 'sl-opt-val', value));
    if (value !== '' && value === current) b.appendChild(el('span', 'sl-opt-tag', '当前'));
    b.addEventListener('click', onPick);
    return b;
  }

  /** POST /api/config 应用切换：成功→合并响应；409→挂起待 SSE done；其他→内联报错。 */
  private async apply(patch: ConfigPatch): Promise<void> {
    if (!this.popup) return;
    const popup = this.popup;
    const status = el('div', 'sl-popup-status busy', '切换中…');
    popup.appendChild(status);
    try {
      const d = await api.saveConfig(patch);
      this.merge({ model: d.model, reasoning_effort: d.reasoning_effort });
      this.setNote('已切换', 5000);
      window.dispatchEvent(new Event('studio:config-saved'));
      this.closePopup();
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        this.pendingPatch = patch;
        this.setNote('轮次进行中，将在本轮结束后生效', 0);
        this.closePopup();
      } else {
        if (this.popup === popup) {
          status.className = 'sl-popup-status err';
          status.textContent = '切换失败：' + (err instanceof Error ? err.message : String(err));
        } else {
          this.setNote('切换失败：' + (err instanceof Error ? err.message : String(err)), 6000);
        }
      }
    }
  }

  private setNote(text: string, ms: number): void {
    this.note = text;
    if (this.noteTimer !== null) {
      window.clearTimeout(this.noteTimer);
      this.noteTimer = null;
    }
    if (ms > 0) {
      this.noteTimer = window.setTimeout(() => {
        this.note = '';
        this.noteTimer = null;
        this.renderHint();
      }, ms);
    }
    this.renderHint();
  }

  private renderHint(): void {
    if (this.note) {
      this.hintEl.textContent = this.note;
      return;
    }
    this.hintEl.textContent = this.staleMsg;
  }

  private async poll(): Promise<void> {
    try {
      const s = await api.status();
      this.staleMsg = '';
      this.el.classList.remove('sl-stale');
      this.snapshot = { ...this.snapshot, ...s };
      this.render();
    } catch (err) {
      // /api/status 未上线或后端不可达：保持占位符，不打断聊天
      this.el.classList.add('sl-stale');
      this.staleMsg = '状态接口暂不可用';
      this.renderHint();
      const msg = err instanceof Error ? err.message : String(err);
      this.el.title = 'GET /api/status 失败：' + msg;
    }
  }

  private render(): void {
    const s = this.snapshot;
    const usage = s.context_usage;
    if (usage) {
      const ratio = clamp01(usage.ratio);
      this.ctxEl.textContent = fmtCompact(usage.used) + '/' + fmtCompact(usage.window);
      this.ring.style.strokeDashoffset = String(RING_C * (1 - ratio));
      this.ring.classList.toggle('warn', ratio >= WARN_RATIO);
      this.ring.title = '上下文占用 ' + Math.round(ratio * 1000) / 10 + '%' +
        ' · ' + fmtCompact(usage.used) + '/' + fmtCompact(usage.window);
    } else {
      this.ctxEl.textContent = '—/—';
      this.ring.style.strokeDashoffset = String(RING_C);
      this.ring.classList.remove('warn');
    }

    this.modelEl.textContent = s.model || '—';
    this.modelEl.title = '当前模型：' + (s.model || '—') + '（点击快速切换）';

    // 思考强度：'max' 直接显示；空/null 表示标准档
    const effort = s.reasoning_effort;
    this.effortEl.textContent = effort ? String(effort) : '—';
    this.effortEl.title = '思考强度：' + (effort ? String(effort) : '标准') + '（点击快速切换）';

    const tps = s.tokens_per_sec;
    this.tpsEl.textContent = tps !== undefined && tps !== null ? fixed1(tps) + ' tok/s' : '— tok/s';

    // W263 缓存命中率：只改文本（铁律 1/2/5——不重建 DOM，不重渲染背景）
    this.renderCache(s.usage);

    const steps = s.steps;
    this.stepsEl.textContent = typeof steps === 'number' && steps >= 1 ? 'step ' + steps : 'step —';
  }

  /**
   * W263: `缓存 78%` = the LATEST LLM stream's cache_read / prompt_tokens.
   * `缓存 —` when the engine has reported no usage yet. The title spells out
   * the exact numbers and the cumulative ratio (tracker.total()).
   */
  private renderCache(u: UsageSnapshot | undefined): void {
    if (!u || !(u.prompt_tokens > 0)) {
      this.cacheEl.textContent = '缓存 —';
      this.cacheEl.title = '缓存命中：暂无引擎用量数据（GET /api/status 的 usage）';
      return;
    }
    const pct = Math.round(clamp01(u.cache_hit_ratio) * 100);
    this.cacheEl.textContent = '缓存 ' + pct + '%';
    const t = u.total;
    this.cacheEl.title =
      '最近一次请求：命中 ' +
      u.cache_read +
      ' / 提示 ' +
      u.prompt_tokens +
      ' tokens' +
      (t
        ? '（累计 ' + (clamp01(t.cache_hit_ratio) * 100).toFixed(1) + '%，命中 ' + t.cache_read + ' / 提示 ' + t.prompt_tokens + ' tokens）'
        : '');
  }
}

function clamp01(v: number): number {
  if (!Number.isFinite(v)) return 0;
  return Math.min(1, Math.max(0, v));
}

function fixed1(v: number): string {
  return Number.isFinite(v) ? v.toFixed(1) : '—';
}

function pickStatusFields(p: StatusSnapshot): StatusSnapshot {
  const out: StatusSnapshot = {};
  if (p.model !== undefined) out.model = p.model;
  if (p.reasoning_effort !== undefined) out.reasoning_effort = p.reasoning_effort;
  if (p.steps !== undefined) out.steps = p.steps;
  if (<REDACTED> !== undefined) out.tokens_per_sec = <REDACTED>;
  if (p.context_usage !== undefined) out.context_usage = p.context_usage;
  if (p.usage !== undefined) out.usage = p.usage; // W263 缓存命中率
  return out;
}

// ============================================================================
// chat.ts — turn 生命周期 + SSE 接线（编排层）：
//   收到 SSE 事件 → 更新 state → 驱动 ui/messages · ui/toolcards · ui/statusbar。
//   发送/取消：读输入（ui/inputbar 回调）→ POST /api/turn | /api/cancel。
// ============================================================================
import { api } from './api';
import { SseClient } from './sse';
import type { Statusline } from './statusline';
import type {
  CompactPayload,
  DonePayload,
  StatusPayload,
  TextPayload,
  ThinkingPayload,
  ToolPayload,
  ToolResultPayload,
} from './types';
import { S } from './state';
import {
  addUserMessage,
  appendText,
  appendThinking,
  applyFinalText,
  assistantHasContent,
  autoscroll,
  endTurn,
  ensureAssistant,
  finalizeAssistant,
  flushTextSegment,
  removeAssistant,
  renderInfoBlock,
} from './ui/messages';
import { applyToolResult, getToolStep, pushToolCard, resetTurnStep } from './ui/toolcards';
import { clearInput, initInputBar, setBusy } from './ui/inputbar';
import {
  feedAssistantDelta,
  finalAssistantDedup,
  resolveActiveSession,
  restoreSessionHistory,
} from './ui/restore';
import {
  cancelStatusFlash,
  finishElapsedTimer,
  flashStatus,
  setStatus,
  setStatusStep,
  setStatusTurn,
  startElapsedTimer,
  stopElapsedTimer,
} from './ui/statusbar';

const PHASE_LABELS: Record<string, string> = {
  completed: '完成',
  cancelled: '已取消',
  error: '出错',
};

// ---- turn lifecycle ----------------------------------------------------------------

function finalizeTurn(phase: string): void {
  endTurn(); // 思考段归属随轮次结束清除（跨轮不跨移）
  const wasStreaming = S.streaming;
  S.streaming = false;
  S.turn = null;
  setBusy(false);
  finishElapsedTimer(); // W263：保留本轮最终耗时（下一轮 start 时重置）
  setStatus(
    PHASE_LABELS[phase] || phase,
    phase === 'error' || phase === 'cancelled' ? 'err' : 'ok',
  );
  if (S.assistant) {
    if (assistantHasContent(S.assistant)) {
      finalizeAssistant(S.assistant);
    } else {
      // 空占位气泡（无正文/思考/工具内容）：不渲染空块
      removeAssistant(S.assistant);
    }
  }
  S.assistant = null;
  if (wasStreaming) autoscroll(true);
}

function onStatus(p: StatusPayload): void {
  if (p.phase === 'start') {
    // 第 23 轮：思考阶段绝不创建 assistant 气泡——只在首个 text delta
    // （onText 内 ensureAssistant）或工具卡需要时才创建；思考期间仅显示思考块。
    cancelStatusFlash(); // W259：/compact 的短暂提示让位给 turn 状态
    endTurn(); // 新轮开始：思考段归属重置（跨轮不跨移）
    if (S.streaming && S.assistant) {
      // 异常残留（理论上 finalizeTurn 已清）：有内容才收尾，空块直接移除
      if (assistantHasContent(S.assistant)) finalizeTurn('completed');
      else removeAssistant(S.assistant);
    }
    S.turn = p.turn ?? null;
    S.streaming = true;
    setBusy(true);
    setStatus('运行中…', 'busy');
    setStatusTurn(p.turn ?? null);
    resetTurnStep(); // W263：新一轮工具步数清零（每个 tool 事件 +1）
    setStatusStep(null);
    startElapsedTimer();
    return;
  }
  if (
    p.turn !== undefined &&
    p.turn !== null &&
    S.turn !== null &&
    p.turn !== S.turn
  ) {
    return;
  }
  if (p.phase === 'completed' || p.phase === 'cancelled' || p.phase === 'error') {
    finalizeTurn(p.phase || '');
    if (p.phase === 'error') {
      // 出错提示作为信息块按序出现在流中
      renderInfoBlock('本轮出错：' + (p.error || '未知错误'), 'err');
    }
  }
  if (p.phase === 'lagged') {
    // 慢客户端：可见信息块（不再静默）
    renderInfoBlock('检测到慢客户端事件（lagged），已合并跳过', 'warn');
  }
  if (p.hint) {
    renderInfoBlock(String(p.hint), 'warn');
  }
}

function onText(p: TextPayload): void {
  if (S.turn === null) S.turn = p.turn ?? null;
  if (p.turn !== undefined && p.turn !== S.turn) return;
  if (S.streaming === false) {
    S.streaming = true;
    setBusy(true);
  }
  // 衔接去重：SSE 重放的增量若与已恢复尾部同内容则吞掉
  const delta = feedAssistantDelta(p.delta || '');
  if (delta === null) return;
  const a = ensureAssistant();
  appendText(a, delta);
}

function onThinking(p: ThinkingPayload): void {
  if (S.turn === null) S.turn = p.turn ?? null;
  if (p.turn !== undefined && p.turn !== S.turn) return;
  appendThinking(p.delta || ''); // 弱化思考段：按事件顺序独立渲染
}

function onTool(p: ToolPayload): void {
  if (S.turn === null) S.turn = p.turn ?? null;
  if (p.turn !== undefined && S.turn !== null && p.turn !== S.turn) return;
  // 连续流：文本段先收尾，工具卡按事件顺序排在文本段之后
  flushTextSegment();
  pushToolCard(p); // 消息流级条目：按事件时间内联在消息流中
  setStatusStep(getToolStep() > 0 ? String(getToolStep()) : null);
  autoscroll();
}

function onToolResult(p: ToolResultPayload): void {
  if (S.turn === null) S.turn = p.turn ?? null;
  if (p.turn !== undefined && S.turn !== null && p.turn !== S.turn) return;
  applyToolResult(p);
  setStatusStep(getToolStep() > 0 ? String(getToolStep()) : null);
  autoscroll();
}

function onDone(p: DonePayload): void {
  if (S.turn === null) S.turn = p.turn ?? null;
  if (p.turn !== undefined && S.turn !== null && p.turn !== S.turn) return;
  const a = S.assistant;
  if (!a) return;
  if (finalAssistantDedup(p.text)) {
    // 整条为已恢复尾部的重放：移除重复气泡
    a.root.remove();
    S.assistant = null;
    return;
  }
  if (typeof p.text === 'string') applyFinalText(a, p.text);
  // done = 一轮模型输出结束；在 status completed/cancelled/error 之前可能还有工具轮次
  autoscroll();
}

// ---- SSE wiring ---------------------------------------------------------------

export function connectSse(statusline: Statusline): SseClient {
  const sse = new SseClient();
  sse.onConn((state) => {
    S.conn = state;
    if (state === 'online') {
      setStatus(S.streaming ? '运行中…' : '就绪 · 在线', S.streaming ? 'busy' : 'ok');
    } else if (state === 'down') {
      setStatus('重连中…', 'err');
    }
  });
  sse.on('status', (p) => {
    try {
      statusline.fromSse(p);
      onStatus(p);
    } catch (err) {
      console.warn('SSE status', err);
    }
  });
  sse.on('text', (p) => {
    try {
      onText(p);
    } catch (err) {
      console.warn('SSE text', err);
    }
  });
  sse.on('thinking', (p) => {
    try {
      onThinking(p);
    } catch (err) {
      console.warn('SSE thinking', err);
    }
  });
  sse.on('tool', (p) => {
    try {
      onTool(p);
    } catch (err) {
      console.warn('SSE tool', err);
    }
  });
  sse.on('tool_result', (p) => {
    try {
      onToolResult(p);
    } catch (err) {
      console.warn('SSE tool_result', err);
    }
  });
  sse.on('done', (p) => {
    try {
      statusline.onSseDone();
      onDone(p);
    } catch (err) {
      console.warn('SSE done', err);
    }
  });
  sse.on('context', (p) => {
    try {
      // 上下文注入/裁剪等系统事件 → 信息块按序出现在流中
      renderInfoBlock(p.text || '上下文事件', p.cls === 'err' ? 'err' : p.cls === 'warn' ? 'warn' : undefined);
    } catch (err) {
      console.warn('SSE context', err);
    }
  });
  sse.on('compact', (p) => {
    try {
      onCompact(p);
    } catch (err) {
      console.warn('SSE compact', err);
    }
  });
  sse.connect();
  return sse;
}

// ---- W259 /compact -------------------------------------------------------------

/** 压缩请求进行中（防连点）。 */
let compacting = false;
/** 本地刚压缩过的时间戳：吞掉同一动作回环回来的 compact SSE，避免重复重载。 */
let localCompactAt = 0;
const LOCAL_COMPACT_DEDUP_MS = 5_000;

/**
 * 收到 compact SSE（本客户端或其它客户端触发的压缩）：
 *   - turn 进行中不打断；
 *   - 只对当前活跃会话重载消息区，其它会话不打扰。
 */
function onCompact(p: CompactPayload): void {
  if (S.streaming) return;
  if (Date.now() - localCompactAt < LOCAL_COMPACT_DEDUP_MS) return; // 本地已处理
  void (async () => {
    const id = await resolveActiveSession();
    if (id === null) return;
    if (p.session && p.session !== id) return;
    await restoreSessionHistory(id);
    flashStatus(p.note || '上下文已压缩', 'ok');
  })();
}

/**
 * `/compact` 命令流程（W259）：
 *   - 仅当输入整体 trim 后精确等于 "/compact" 时触发——命令被消费（清空输入框），
 *     但绝不写入用户气泡、绝不 POST /api/turn，因此不产生普通 turn；
 *   - 三态提示（成功 / 无需压缩 / 错误）走状态栏短暂提示，不打断当前视图；
 *   - 成功后重载消息区（复用 restoreSessionHistory 的离屏双缓冲替换）。
 *   - 409（turn 进行中）/500（摘要失败）只提示错误，不改任何本地状态。
 */
async function runCompact(): Promise<void> {
  if (compacting) return;
  compacting = true;
  clearInput(); // 命令消费：输入框清空，但不当普通消息发送
  try {
    const id = await resolveActiveSession();
    if (id === null) {
      flashStatus('压缩失败：未找到活跃会话', 'err', 8000);
      return;
    }
    setStatus('压缩中…', 'busy');
    const r = await api.compactSession(id);
    if (r.compacted === false) {
      flashStatus(r.note || '历史不足，无需压缩', 'ok');
      return;
    }
    localCompactAt = Date.now();
    flashStatus(r.note || '已压缩：摘要轮 + 最近4轮', 'ok');
    await restoreSessionHistory(id); // 消息区 reload
  } catch (err) {
    flashStatus(
      '压缩失败：' + (err instanceof Error ? err.message : String(err)),
      'err',
      8_000,
    );
  } finally {
    compacting = false;
  }
}

// ---- send / cancel -------------------------------------------------------------

export function initChat(): void {
  initInputBar({
    send(text) {
      const t = text.trim();
      if (!t) return;
      // W259：/compact 是命令而非消息——走压缩流程，不进普通发送路径
      if (t === '/compact') {
        void runCompact();
        return;
      }
      if (S.streaming) return;
      addUserMessage(t);
      clearInput();
      S.streaming = true;
      S.turn = null;
      setBusy(true);
      setStatus('启动中…', 'busy');
      resetTurnStep(); // W263：发送即清零当前轮步数（SSE start 到达前也正确）
      setStatusStep(null);
      void api
        .turn(t)
        .then((r) => {
          if (S.turn === null && r.turn !== undefined) S.turn = r.turn;
          setStatusTurn(S.turn !== null ? S.turn : r.turn ?? 0);
          if (S.turn === null) startElapsedTimer();
          // 第 23 轮：不在此创建占位气泡——首个 text delta / 工具卡才创建
          setStatus('运行中…', 'busy');
        })
        .catch((err: unknown) => {
          // 403/409/… 直接展示
          S.streaming = false;
          setBusy(false);
          stopElapsedTimer();
          setStatus('发送失败：' + (err instanceof Error ? err.message : String(err)), 'err');
        });
    },
    cancel() {
      if (!S.streaming) return;
      setStatus('取消中…', 'busy');
      void api.cancel().catch((err: unknown) => {
        setStatus('取消失败：' + (err instanceof Error ? err.message : String(err)), 'err');
      });
    },
  });
}

// ============================================================================
// SSE client — typed wrappers around the /api/events stream.
// Event names preserved: status/text/thinking/tool/tool_result/done.
// 责任边界：仅解析/分发事件，不做状态归并（归并在 chat.ts）。
// Each event: {"turn":N,"seq":M,"payload":{...}, ...}
// ============================================================================
import type {
  CompactPayload,
  ConnState,
  ContextPayload,
  DonePayload,
  SseEnvelope,
  SseEventName,
  StatusPayload,
  TextPayload,
  ThinkingPayload,
  ToolPayload,
  ToolResultPayload,
} from './types';

export interface SseHandlerMap {
  status: (p: StatusPayload) => void;
  text: (p: TextPayload) => void;
  thinking: (p: ThinkingPayload) => void;
  tool: (p: ToolPayload) => void;
  tool_result: (p: ToolResultPayload) => void;
  done: (p: DonePayload) => void;
  context: (p: ContextPayload) => void;
  compact: (p: CompactPayload) => void;
}

export type SseHandler<K extends SseEventName> = SseHandlerMap[K];

/**
 * W263: the envelope carries the turn/seq framing while the payload carries the
 * event body ({"turn":N,"seq":M,"payload":{...}}). Handlers read fields off ONE
 * flat object (chat.ts reads p.turn / p.phase / p.delta), so merge the envelope
 * fields into the payload WITHOUT dropping any payload field. Non-object
 * payloads (defensive) are passed through untouched.
 */
function withEnvelope(payload: unknown, env: SseEnvelope): unknown {
  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    return payload;
  }
  const out = { ...(payload as Record<string, unknown>) };
  if (env.turn !== undefined && out.turn === undefined) out.turn = env.turn;
  if (env.seq !== undefined) out.seq = env.seq;
  return out;
}

const EVENT_NAMES: readonly SseEventName[] = [
  'status',
  'text',
  'thinking',
  'tool',
  'tool_result',
  'done',
  'context',
  'compact',
];

export class SseClient {
  private es: EventSource | null = null;
  private handlers = new Map<SseEventName, Set<(p: unknown) => void>>();
  private connCbs = new Set<(state: ConnState) => void>();

  constructor(readonly url = '/api/events') {}

  on<K extends SseEventName>(name: K, handler: SseHandler<K>): void {
    let set = this.handlers.get(name);
    if (!set) {
      set = new Set();
      this.handlers.set(name, set);
    }
    set.add(handler as (p: unknown) => void);
  }

  onConn(cb: (state: ConnState) => void): void {
    this.connCbs.add(cb);
  }

  connect(): void {
    this.close();
    const es = new EventSource(this.url);
    this.es = es;
    es.onopen = () => this.emitConn('online');
    es.onerror = () => this.emitConn('down');
    for (const name of EVENT_NAMES) {
      es.addEventListener(name, (e: MessageEvent<string>) => {
        try {
          const env = JSON.parse(e.data) as SseEnvelope;
          const payload = env.payload !== undefined ? env.payload : env;
          this.emit(name, withEnvelope(payload, env));
        } catch (err) {
          console.warn('[sse] failed to parse', name, err);
        }
      });
    }
  }

  close(): void {
    if (this.es) {
      this.es.close();
      this.es = null;
    }
  }

  private emit(name: SseEventName, payload: unknown): void {
    const set = this.handlers.get(name);
    if (!set) return;
    for (const h of set) {
      try {
        (h as (p: unknown) => void)(payload);
      } catch (err) {
        console.warn('[sse] handler failed for', name, err);
      }
    }
  }

  private emitConn(state: ConnState): void {
    for (const cb of this.connCbs) {
      try {
        cb(state);
      } catch {
        /* ignore listener errors */
      }
    }
  }
}

// ============================================================================
// ui/messages.ts — 消息流（单一职责，W240 连续事件流重构）：
//   一轮 = 按事件真实时间顺序渲染成一条连续流：
//     用户消息 → 思考段（弱化块，按序）→ 文本段（markdown 气泡）→
//     工具调用卡（内联条目）→ 工具结果 → 继续文本段 → ……
//   文本增量按节拍重渲染；工具事件到达时当前文本段收尾（flushTextSegment），
//   后续文本开启新段 —— 不再按"思考/文本/工具"分区聚合。
//   thinking 弱化为独立信息块按序出现；context/status 类事件渲染为信息块。
// ============================================================================
import { $, el, esc, fmtNow, need } from '../utils/dom';
import { highlightCode } from '../utils/hljs';
import { marked } from 'marked';
import type { AssistantView } from './view';
import { S } from '../state';
import { railAdd, railReset, railSync } from './rail';
import { resetToolCards } from './toolcards';

marked.setOptions({ breaks: true, gfm: true });

const MsgsEl = need<HTMLElement>('#messages');

// ---- markdown ---------------------------------------------------------------
/** Render markdown to safe-enough HTML. */
export function md(text: string): string {
  try {
    return marked.parse(text, { async: false }) as string;
  } catch {
    return '<pre>' + esc(text) + '</pre>';
  }
}

// ---- scrolling ----------------------------------------------------------------
/** 粘性自动滚动：仅在用户接近底部时跟随；force 用于完成/新消息时。 */
export function autoscroll(force = false): void {
  const nearBottom = MsgsEl.scrollTop + MsgsEl.clientHeight >= MsgsEl.scrollHeight - 200;
  if (force || nearBottom) MsgsEl.scrollTop = MsgsEl.scrollHeight;
}

export function hideEmptyHint(): void {
  const hint = $('#emptyHint');
  if (hint) hint.classList.add('hidden');
}

/** Rebuild the empty state exactly as it shipped in index.html. */
export function renderEmptyHint(): void {
  MsgsEl.innerHTML = '';
  const hint = el('div', 'empty-hint empty-hint-fresh');
  hint.id = 'emptyHint';
  hint.appendChild(el('div', 'empty-mark', '◇'));
  hint.appendChild(el('div', 'empty-title', 'Celestea Studio'));
  hint.appendChild(el('div', 'empty-sub', '在下方输入消息开始对话 · Enter 发送 · Shift+Enter 换行'));
  MsgsEl.appendChild(hint);
}

/** 助手文本段是否已有内容（占位判定）。 */
export function assistantHasContent(view: AssistantView): boolean {
  return view.text.trim() !== '' || view.content.childElementCount > 0;
}

/** 直接移除空占位助手气泡（不渲染空块）。 */
export function removeAssistant(view: AssistantView): void {
  view.root.remove();
  S.assistant = null;
}

/** 清空消息流并重建空态（/api/clear 成功后调用；同时重置流式状态）。 */
export function resetMessages(): void {
  if (renderTimer !== null) {
    window.clearTimeout(renderTimer);
    renderTimer = null;
  }
  S.assistant = null;
  S.turn = null;
  thinkSeg = null;
  lastTextCol = null;
  resetToolCards(); // 工具卡片（消息流级条目）复位
  railReset(); // 消息 rail 复位
  renderEmptyHint();
}

// ---- 流式正文渲染节流 ---------------------------------------------------------
const RENDER_INTERVAL = 60; // ms —— 重渲染节拍（兼顾流畅与 CPU）
let renderTimer: number | null = null;
let renderDeadline = 0;

function renderTextView(view: AssistantView): void {
  view.content.innerHTML = md(view.text);
  highlightCode(view.content);
  autoscroll();
  railSync();
}

function scheduleTextView(view: AssistantView): void {
  if (renderTimer !== null) return; // 已有一次节拍排队
  const wait = Math.max(0, renderDeadline + RENDER_INTERVAL - performance.now());
  renderTimer = window.setTimeout(() => {
    renderTimer = null;
    renderDeadline = performance.now();
    renderTextView(view);
  }, wait);
}

/** 立即冲刷（turn 结束 / done 事件 / 最终文本到来时调用）。 */
function flushTextView(view: AssistantView): void {
  if (renderTimer !== null) {
    window.clearTimeout(renderTimer);
    renderTimer = null;
  }
  renderDeadline = performance.now();
  renderTextView(view);
}

/** 增量追加正文 delta（节拍渲染，不逐字重排）。 */
export function appendText(view: AssistantView, delta: string): void {
  view.text += delta || '';
  scheduleTextView(view);
}

/** Sync final assistant text from the done event. */
export function applyFinalText(view: AssistantView, text: string): void {
  if (typeof text !== 'string' || !text || view.text === text) return;
  view.text = text;
  flushTextView(view);
}

/** 冻结当前文本段：有内容则收尾为完整气泡，并解除当前段（工具事件/新段前调用）。 */
export function flushTextSegment(): void {
  if (S.assistant) {
    const a = S.assistant;
    S.assistant = null;
    if (assistantHasContent(a)) {
      a.bubble.classList.remove('streaming');
      a.bubble.classList.add('complete');
      flushTextView(a);
      autoscroll(true);
    } else {
      a.root.remove(); // 空占位不渲染
    }
  }
}

// ---- thinking（弱化独立段，按事件顺序出现，不再聚合进气泡） ----------------------

interface ThinkSeg {
  root: HTMLElement;   // .mcol 根（含折叠状态 class）
  head: HTMLElement;   // 标题行（可点折叠/展开）
  body: HTMLElement;   // 内容
  text: string;
}

let thinkSeg: ThinkSeg | null = null;
/**
 * 同轮最近文本段（含已被工具事件截断收尾的）：thinking 重排的目标锚点。
 * 工具截断场景下 S.assistant 已置空，但思考块仍须位于对应文本块上方。
 */
let lastTextCol: HTMLElement | null = null;

/** 轮次结束/新轮开始：清除思考段归属与文本段锚点（跨轮不跨移；DOM 保留）。 */
export function endTurn(): void {
  thinkSeg = null;
  lastTextCol = null;
}

/** Append a thinking delta（弱化块：左侧色条 + 浅色底 + 小字；独立成段）。
 * 第 22 轮重排规则收紧（任何到达顺序下成立）：
 *   思考块的目标位置 = 同轮最近文本块的正上方（紧贴）。目标 = 当前流式
 *   文本段（S.assistant.root）若存在，否则为 lastTextCol（同轮最近、含被
 *   tool 截断收尾的文本段）。若思考块当前位于目标之后（无论中间隔着
 *   工具卡/信息块等任何段落）→ insertBefore 局部前移到目标正上方；
 *   已在目标之前 → 不动。跨轮：endTurn() 清 thinkSeg/lastTextCol，绝不串位。
 */
export function appendThinking(delta: string): void {
  if (!thinkSeg) {
    hideEmptyHint();
    const root = el('div', 'mcol');
    const msg = el('div', 'msg think-seg');
    const cap = el('div', 'msg-caption think-head') as HTMLElement;
    cap.appendChild(el('span', 'who', '思考'));
    const foldMark = el('span', 'think-fold-mark', '▾');
    cap.appendChild(foldMark);
    cap.appendChild(el('span', 'think-time', fmtNow()));
    msg.appendChild(cap);
    const bubble = el('div', 'bubble think-seg-bubble');
    const body = el('div', 'think-seg-body');
    bubble.appendChild(body);
    const folded = el('div', 'think-seg-folded', '思考已折叠，点击展开');
    bubble.appendChild(folded);
    msg.appendChild(bubble);
    root.appendChild(msg);
    MsgsEl.appendChild(root);
    thinkSeg = { root, head: cap, body, text: '' };
    body.textContent = '思考中…'; // 流式思考占位态（弱化）
    // 点击标题行折叠/展开（第 23 轮：流式思考中不折叠）
    cap.addEventListener('click', () => {
      if (thinkSeg !== null && S.streaming) return; // 流式思考中不折叠
      root.classList.toggle('collapsed');
      foldMark.textContent = root.classList.contains('collapsed') ? '▸' : '▾';
    });
  }
  // 重排：目标 = 当前文本段 ?? 同轮最近文本段（含 tool 截断收尾的）
  const target = S.assistant?.root ?? lastTextCol;
  if (target && thinkSeg.root.compareDocumentPosition(target) & Node.DOCUMENT_POSITION_FOLLOWING) {
    // 思考块位于目标之后（中间可隔工具卡等）→ 紧贴目标上方
    MsgsEl.insertBefore(thinkSeg.root, target);
  }
  thinkSeg.text += delta || '';
  thinkSeg.body.textContent = thinkSeg.text === '' ? '思考中…' : thinkSeg.text;
  autoscroll();
  railSync();
}

// ---- 信息块（context/status 类事件：注入、lagged、error 提示等） ------------------

/** 渲染一条可见信息块（按序出现在流中；样式与普通消息区分：左侧色条 + 浅色底）。 */
export function renderInfoBlock(text: string, cls?: 'err' | 'warn'): void {
  if (!text) return;
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg info' + (cls ? ' ' + cls : ''));
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '系统'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble info-bubble');
  const body = el('div', 'content info-content');
  body.textContent = text;
  bubble.appendChild(body);
  msg.appendChild(bubble);
  col.appendChild(msg);
  MsgsEl.appendChild(col);
  autoscroll(true);
}

// ---- message builders ----------------------------------------------------------

export function addUserMessage(text: string, container: HTMLElement = MsgsEl): void {
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg user');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '你'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble');
  const body = el('div', 'content');
  body.textContent = text;
  body.style.whiteSpace = 'pre-wrap';
  bubble.appendChild(body);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
  railAdd(col, 'user');
  railSync();
  autoscroll(true);
}

/** 获取当前文本段视图或创建新的流式文本气泡（连续流中的一段；container 用于离屏构建）。 */
export function ensureAssistant(container: HTMLElement = MsgsEl): AssistantView {
  if (S.assistant) return S.assistant;
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg assistant');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', 'Studio'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble streaming');
  const content = el('div', 'content');
  bubble.appendChild(content);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
  railAdd(col, 'assistant');
  railSync();

  // think/cards 字段为类型兼容保留（不挂载；thinking/工具卡均独立成段）
  const view: AssistantView = {
    root: msg,
    bubble,
    think: document.createElement('details'),
    thinkBody: document.createElement('div'),
    thinkTime: document.createElement('span'),
    cards: document.createElement('div'),
    content,
    text: '',
    thinkText: '',
    ops: new Map(),
    steps: 0,
  };
  lastTextCol = col; // 同轮最近文本段（thinking 重排锚点）
  S.assistant = view;
  autoscroll(true);
  return view;
}

/** 文本段收尾（turn 结束 / done 冲刷）。 */
export function finalizeAssistant(view: AssistantView): void {
  view.bubble.classList.remove('streaming');
  view.bubble.classList.add('complete');
  flushTextView(view);
  autoscroll(true);
}

// ============================================================================
// ui/statusbar.ts — 底部状态栏（单一职责）：连接/阶段文本、turn/step、耗时计时。
// 不感知 turn 生命周期——由 chat.ts 在合适时机调用本模块。
// ============================================================================
import { S } from '../state';
import { fmtTime, need } from '../utils/dom';

const StatusText = need<HTMLElement>('#statusText');
const StatusDot = need<HTMLElement>('#statusDot');
const StatusTurn = need<HTMLElement>('#statusTurn');
const StatusStep = need<HTMLElement>('#statusStep');
const StatusTime = need<HTMLElement>('#statusTime');

export function setStatus(text: string, cls?: string): void {
  StatusText.textContent = text;
  StatusDot.className = 'dot' + (cls ? ' ' + cls : '');
}

export function setStatusTurn(n: number | null): void {
  StatusTurn.textContent = typeof n === 'number' && n >= 1 ? 'turn ' + n : 'turn —';
}

export function setStatusStep(n: number | string | null): void {
  StatusStep.textContent = 'step ' + (n && String(n) !== '' ? String(n) : '—');
}

function tickTimer(): void {
  if (!S.streaming) return;
  StatusTime.textContent = fmtTime((Date.now() - S.t0) / 1000);
}

/** 启动（或重置）耗时计时：t0 取当前时刻。 */
export function startElapsedTimer(): void {
  S.t0 = Date.now();
  stopElapsedTimer();
  S.msgTimer = window.setInterval(tickTimer, 500);
  tickTimer();
}

export function stopElapsedTimer(): void {
  if (S.msgTimer !== null) {
    window.clearInterval(S.msgTimer);
    S.msgTimer = null;
  }
}

/**
 * W263：结束一轮计时 —— 停表并**保留最终耗时**（不再归零成 00:00）；
 * 下一轮 startElapsedTimer() 才重置。tickTimer 依赖 S.streaming，
 * 所以这里直接写最后一帧。
 */
export function finishElapsedTimer(): void {
  stopElapsedTimer();
  if (S.t0 > 0) StatusTime.textContent = fmtTime((Date.now() - S.t0) / 1000);
}

// ---- 一次性操作提示（W259 /compact） --------------------------------------------

let flashTimer: number | null = null;

/** 取消尚未到期的短暂提示（新一轮开始时调用，避免覆盖 turn 状态）。 */
export function cancelStatusFlash(): void {
  if (flashTimer !== null) {
    window.clearTimeout(flashTimer);
    flashTimer = null;
  }
}

/**
 * 短暂提示：立即写入状态栏，ms 后自动恢复连接态文案（W259 /compact 三态提示）。
 * 期间若进入 turn（S.streaming），恢复动作自动让位，不覆盖运行状态。
 */
export function flashStatus(text: string, cls: string, ms = 6000): void {
  cancelStatusFlash();
  setStatus(text, cls);
  flashTimer = window.setTimeout(() => {
    flashTimer = null;
    if (S.streaming) return; // turn 正在跑：状态栏归 turn 生命周期管
    if (S.conn === 'online') setStatus('就绪 · 在线', 'ok');
    else if (S.conn === 'down') setStatus('重连中…', 'err');
  }, ms);
}

// ============================================================================
// ui/inputbar.ts — 输入栏（单一职责）：textarea 自动增高、Enter 发送、
// 发送/取消按钮状态。业务逻辑通过回调交给 chat.ts。
// ============================================================================
import { need } from '../utils/dom';

export interface InputBarHandlers {
  /** 发送；text 为原始输入内容（trim/校验由调用方负责）。 */
  send(text: string): void;
  cancel(): void;
}

const MAX_HEIGHT = 240;

let sendBtn: HTMLButtonElement | null = null;
let cancelBtn: HTMLButtonElement | null = null;

export function initInputBar(h: InputBarHandlers): void {
  const input = need<HTMLTextAreaElement>('#input');
  sendBtn = need<HTMLButtonElement>('#btnSend');
  cancelBtn = need<HTMLButtonElement>('#btnCancel');

  const autoGrow = () => {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, MAX_HEIGHT) + 'px';
  };

  sendBtn.addEventListener('click', () => h.send(input.value));
  cancelBtn.addEventListener('click', () => h.cancel());
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      h.send(input.value);
    }
  });
  input.addEventListener('input', autoGrow);
  window.setTimeout(autoGrow, 0);
}

/** 发送成功后清空输入框并复位高度。 */
export function clearInput(): void {
  const input = need<HTMLTextAreaElement>('#input');
  input.value = '';
  input.style.height = 'auto';
  input.style.height = Math.min(input.scrollHeight, MAX_HEIGHT) + 'px';
}

/** 切换 发送/取消 按钮状态。 */
export function setBusy(busy: boolean): void {
  if (sendBtn) sendBtn.disabled = busy;
  if (cancelBtn) cancelBtn.classList.toggle('hidden', !busy);
}

// ============================================================================
// ui/rail.ts — 「灵动消息选择条」v3（W238 删旧重做）
// ----------------------------------------------------------------------------
// ★ 锚定策略（与 v1/v2 的本质区别 —— 锚定于聊天区左侧留白带、不贴消息列）：
//   1) 轨道不再挂进滚动容器 #messages，而是以 position:absolute 固定在
//      聊天主区 #main（由 styles/rail.css 设 position:relative）内，几何上
//      与 #messages 视口严格重合（top/height 实时同步），left 固定在
//      #main 左缘内侧 8px —— 即「侧栏 + 拖宽分隔条」右侧的留白带最左端。
//      #messages 滚动时轨道纹丝不动 → 不随消息滚动而移动。
//   2) 横向坐标策略：留白带宽 gw = .mcol 左缘 − #main 左缘（= #messages
//      内边距 + mcol 居中的富余宽度）。长条自留白带左端向右生长，最长
//      min(110, gw−26)，即永远在 .mcol 左缘前 ≥18px 收住 → 不贴消息列
//      边缘、不遮消息内容（悬停/点击不会碰到消息气泡）。
//   3) 侧栏拖宽 / 窗口缩放 → ResizeObserver(#main,#messages) 重算几何：
//      gw ≥ 64px 正常态；24–64px 细条化（更短更细、仍可交互）；
//      < 24px 整体隐藏。任何档位都不溢出留白带。
// ★ 纵向排列方案（「垂直居中于视口 / 跟随可见区域」二选一，取前者为主）：
//   默认「垂直居中于视口」——长条按消息顺序自顶向下紧凑排列（自然节距
//   15px = 条高 12px + 间隙 3px；条数增多时节距自适应压缩、下限 5px），
//   条组整体垂直居中于消息视口。会话极长（最小节距仍放不下）时自动切换
//   「跟随可见区域」子集模式：只渲染当前视口附近的条目并随滚动实时刷新，
//   条组仍垂直居中。选固定条组而非逐消息贴位，是让长条 Y 与消息高度解耦：
//   流式输出期间消息高度变化不会拉扯选择条（位置/计数同步 = railSync
//   重排 + 新增消息即新增长条）。
// ★ 灵动交互：鼠标进入条带（x∈[轨道左−6, 轨道右+14]，y∈消息视口）→
//   距鼠标最近的长条权重 1（最长、吸附），上下邻居按 |Δy| 线性衰减
//   （fisheye）；hover 停留 350ms 弹预览卡（该消息首行前 40 字 + 分割线
//   + 助手回复首行前 40 字，数据全部取自已渲染消息 DOM，零网络请求）；
//   点击长条 → scrollIntoView 平滑定位到对应消息。交互统一由 #main 级
//   监听 + 命中判定完成（节距压缩后条高可到 3px，DOM 级 hover 不可靠）。
// ============================================================================
import { el } from '../utils/dom';

// ---- 紧凑几何（第 16 轮：细条 —— 自然高 5px、间隙 4px；hover 不变长不变粗） ----
const ITEM_H = 5;              // 自然条高（hover 保持）
const GAP = 4;                 // 自然间隙
const PITCH_NATURAL = ITEM_H + GAP; // 9px
const PITCH_MIN = 4;           // 压缩节距下限（条 2px + 间隙 2px）
const PAD_Y = 8;               // 条组上下留白
const BASE_W = 7;              // 未悬停细条宽
const MAX_W = 110;             // 正常态最长条宽上限
const GUTTER_NORMAL = 64;      // 留白 ≥ 此值：正常态
const GUTTER_HIDE = 24;        // 留白 < 此值：隐藏
const RANGE = 80;              // fisheye 纵向衰减半径（px，第 21 轮：第 19/20 轮中间值）
const HIT_BOOST = 6;            // 命中条宽度上限额外上浮（px，k=1 时；第 21 轮回调）
const BASE_OPACITY = 0.3;       // 非邻近条透明度基准（第 21 轮回调：0.30+0.40k，上限 0.7）
const PREVIEW_MS = 150;        // hover 停留防抖（第 19 轮：既瞬时又不误触）
const PREVIEW_CHARS = 40;      // 预览首行前 N 字
const MAX_ROWS = 20;           // 轮条显示上限：只显示最近 20 轮，更早折叠为顶部「⋯」

/** 一根长条 = 一轮（一问一答合并）：user 消息与其后 assistant 回复（含工具活动）。 */
interface RailItem {
  startCol: HTMLElement; // 轮起点（user 消息；孤立 assistant 为其自身）
  cols: HTMLElement[];   // 该轮全部消息列（user + assistant 段）
  hasReply: boolean;     // 该轮是否已有 assistant 回复
  el: HTMLElement;
  y: number;             // 长条中心在轨道内的 Y（layout 计算）
  visible: boolean;
  fold: number;          // >0 = 折叠条（表示更早 N 轮已折叠）
}

let mainEl: HTMLElement | null = null;
let msgsEl: HTMLElement | null = null;
let track: HTMLElement | null = null;
let card: HTMLElement | null = null;
let items: RailItem[] = [];
let foldItem: RailItem | null = null; // 「更早 N 轮已折叠」顶部短条（items 之外）
let hoverItem: RailItem | null = null;
let hoverTimer: number | null = null;
let syncQueued = false;
let moveQueued = false;
let moveX = -1;
let moveY = -1;

// 几何缓存（layout() 刷新；pointer 命中判定直接读，避免每帧 reflow）
let railX = 8;
let railTop = 0;
let railH = 0;
let railW = MAX_W; // 当前档位的最大条宽
let pitch = PITCH_NATURAL;
let modeAll = true;

/** 参与布局/交互的全部条目（含折叠条）。 */
function allItems(): RailItem[] {
  return foldItem ? [foldItem, ...items] : items;
}

// ---- 轨道与几何 ---------------------------------------------------------------

function ensureTrack(): boolean {
  if (!mainEl) return false;
  if (!track || !track.isConnected) {
    track = document.createElement('div');
    track.className = 'railv3';
    mainEl.appendChild(track);
  }
  return true;
}

/** 留白带宽：.mcol 左缘 − #main 左缘（mcol 居中富余 + #messages 内边距）。 */
function gutterWidth(): number {
  if (!mainEl || !msgsEl) return 0;
  const col = msgsEl.querySelector<HTMLElement>('.mcol');
  const m = mainEl.getBoundingClientRect();
  if (!col) return Math.max(0, m.width - 24);
  return Math.max(0, col.getBoundingClientRect().left - m.left);
}

/** 全量重排：横向档位 + 纵向节距 + 条组居中（railSync / 滚动 / 尺寸变化）。 */
function layout(): void {
  if (!mainEl || !msgsEl || !track) return;
  const m = mainEl.getBoundingClientRect();
  const v = msgsEl.getBoundingClientRect();
  railTop = Math.max(0, v.top - m.top);
  railH = v.height;

  // ---- 横向：留白带档位（正常 / 细条化 / 隐藏） ----
  const gw = gutterWidth();
  if (gw < GUTTER_HIDE) {
    track.style.display = 'none';
    railW = 0;
    syncCard();
    return;
  }
  track.style.display = '';
  const thin = gw < GUTTER_NORMAL;
  railX = 8;
  railW = thin ? Math.max(6, gw - 24) : Math.min(MAX_W, gw - 26);
  track.classList.toggle('railv3-thin', thin);
  track.style.left = railX + 'px';
  track.style.top = railTop + 'px';
  track.style.height = railH + 'px';

  // ---- 纵向：节距自适应；轮条上限 20 + 顶部折叠条 ----
  const usable = Math.max(0, railH - 2 * PAD_Y);
  if (items.length === 0) {
    if (foldItem) {
      foldItem.el.remove();
      foldItem = null;
    }
    syncCard();
    return;
  }
  // 折叠条：超过 MAX_ROWS 轮 → 旧轮折叠为顶部「⋯」短条
  const foldN = items.length > MAX_ROWS ? items.length - MAX_ROWS : 0;
  if (foldN > 0) {
    if (!foldItem || !foldItem.el.isConnected) {
      foldItem = {
        startCol: items[items.length - MAX_ROWS]!.startCol,
        cols: [],
        hasReply: false,
        el: document.createElement('div'),
        y: 0,
        visible: false,
        fold: foldN,
      };
      foldItem.el.className = 'railv3-item railv3-fold';
      foldItem.el.textContent = '⋯';
      foldItem.el.title = '更早的 ' + foldN + ' 轮已折叠';
      track!.appendChild(foldItem.el);
    }
    foldItem.fold = foldN;
  } else if (foldItem) {
    foldItem.el.remove();
    foldItem = null;
  }
  const bars = allItems();
  const count = bars.length;
  let shown: RailItem[];
  if (count * PITCH_MIN <= usable) {
    modeAll = true;
    pitch = Math.max(PITCH_MIN, Math.min(PITCH_NATURAL, usable / count));
    shown = bars;
  } else {
    modeAll = false;
    shown = viewWindow();
    pitch = Math.max(PITCH_MIN, Math.min(PITCH_NATURAL, usable / Math.max(1, shown.length)));
  }
  const stripTop = PAD_Y + Math.max(0, (usable - shown.length * pitch) / 2);
  const barH = Math.max(2, pitch - GAP);
  for (const it of bars) {
    const i = shown.indexOf(it);
    if (i < 0) {
      it.visible = false;
      it.el.style.display = 'none';
      continue;
    }
    it.visible = true;
    it.el.style.display = '';
    it.y = stripTop + i * pitch + pitch / 2;
    it.el.style.top = (it.y - barH / 2) + 'px';
    it.el.style.setProperty('--barh', barH + 'px'); // 高度经 CSS 变量，hover 可加高
  }
  syncCard();
}

/** 消息列中心在滚动内容里的 Y（rect 法，不依赖 offsetParent）。 */
function docCenterY(it: RailItem): number {
  const v = msgsEl!.getBoundingClientRect();
  const c = it.startCol.getBoundingClientRect();
  return c.top - v.top + msgsEl!.scrollTop + c.height / 2;
}

/** 超长会话：只渲染视口上下各 ~0.2 屏范围内的条目（跟随可见区域）。 */
function viewWindow(): RailItem[] {
  const st = msgsEl!.scrollTop;
  const lo = st - railH * 0.2;
  const hi = st + railH * 1.2;
  return items.filter((it) => {
    const y = docCenterY(it);
    return y >= lo && y <= hi;
  });
}

// ---- 预览卡片（数据取自 DOM，零请求） -------------------------------------------

function removeCard(): void {
  if (card) {
    card.remove();
    card = null;
  }
}

/** 消息内容首行前 N 字（压平空白、取第一个非空行）。 */
function firstLine(col: HTMLElement): string {
  const c = col.querySelector('.content');
  const raw = (c?.textContent ?? '').replace(/[ \t]+/g, ' ').trim();
  if (!raw) return '';
  const line = raw.split('\n').map((s) => s.trim()).find((s) => s.length > 0) ?? '';
  return line.length > PREVIEW_CHARS ? line.slice(0, PREVIEW_CHARS) + '…' : line;
}

/** 该轮第一条 assistant 回复的内容首行（轮内查找，不跨轮）。 */
function replyLine(it: RailItem): string {
  for (const col of it.cols) {
    if (col.querySelector('.msg.assistant')) return firstLine(col);
  }
  return '';
}

function showCard(it: RailItem): void {
  if (!mainEl || !it.visible) return;
  removeCard();
  card = el('div', 'railv3-card');
  if (it.fold > 0) {
    // 折叠条：hover 提示更早轮数
    const ql = el('div', 'railv3-card-q');
    ql.appendChild(el('span', 'railv3-card-tag', '⋯'));
    ql.appendChild(el('span', null, '更早的 ' + it.fold + ' 轮已折叠'));
    card.appendChild(ql);
  } else {
    const q = firstLine(it.startCol);
    if (q) {
      const ql = el('div', 'railv3-card-q');
      ql.appendChild(el('span', 'railv3-card-tag', 'Q'));
      ql.appendChild(el('span', null, q));
      card.appendChild(ql);
    }
    if (it.hasReply) {
      const a = replyLine(it);
      if (a) {
        card.appendChild(el('div', 'railv3-card-sep'));
        const al = el('div', 'railv3-card-a');
        al.appendChild(el('span', 'railv3-card-tag', 'A'));
        al.appendChild(el('span', null, a));
        card.appendChild(al);
      }
      // 流式回复进行中（hasReply 但尚无内容）：不显示 A 行
    } else {
      card.appendChild(el('div', 'railv3-card-sep'));
      const al = el('div', 'railv3-card-a railv3-card-noa');
      al.appendChild(el('span', 'railv3-card-tag', 'A'));
      al.appendChild(el('span', null, '（无回复）'));
      card.appendChild(al);
    }
  }
  mainEl.appendChild(card);
  positionCard(it);
}

/** 预览锚定（第 18 轮）：必须出现在被 hover 细条的右侧、与该条同一垂直位置——
 *  top = 条 getBoundingClientRect().top（相对 #main），x = 条右缘 + 8px；
 *  越界（太靠下）向上收，横向不出主区。流式高度变化时条移动 → railSync →
 *  layout → syncCard 重新调用本函数，预览跟随该条。 */
function positionCard(it: RailItem): void {
  if (!card || !mainEl) return;
  const m = mainEl.getBoundingClientRect();
  const r = it.el.getBoundingClientRect();
  const ch = card.offsetHeight;
  // 同一垂直位置：按条 top 对齐；越界上下收（默认向上收）
  let top = r.top - m.top;
  top = Math.max(railTop + 4, Math.min(top, railTop + railH - ch - 4));
  // x = 条右缘 + 8px；越界右收进主区
  const left = Math.min(r.right - m.left + 8, m.width - 288);
  card.style.top = top + 'px';
  card.style.left = Math.max(railX + 4, left) + 'px';
}

/** layout 后同步预览卡（悬停条被重排/隐藏时跟随或关闭）。 */
function syncCard(): void {
  if (!card) return;
  if (!hoverItem || !hoverItem.visible) {
    removeCard();
    return;
  }
  positionCard(hoverItem);
}

// ---- 交互（fisheye + hover 停留预览 + 点击定位） --------------------------------

/** 第 18 轮：恢复「变长」——水平长度 fisheye（Codex 式：临近者最长、
 *  两侧按邻近度线性递减），细条高度保持 5px 不变（绝不加粗加高）；
 *  变长为主、微亮为辅：opacity 0.35→0.7 随同一权重。 */
function setGrow(it: RailItem, g: number): void {
  const k = Math.max(0, Math.min(1, g));
  // 第 20 轮：命中条（k=1）宽度上限小幅上浮 HIT_BOOST，让选中条突出；
  // absolute 定位条改 inline width 不触发布局重排，保持 5px 高不变形；
  // 过渡 85ms 轻 ease-out（见 rail.css）
  const w = BASE_W + k * Math.max(0, railW - BASE_W) + (k >= 1 ? HIT_BOOST : 0);
  it.el.style.width = w.toFixed(1) + 'px';
  it.el.style.opacity = (BASE_OPACITY + (0.7 - BASE_OPACITY) * k).toFixed(3); // 0.30+0.40k
}

function clearHover(): void {
  if (hoverTimer !== null) {
    window.clearTimeout(hoverTimer);
    hoverTimer = null;
  }
  hoverItem = null;
  removeCard();
  for (const it of items) it.el.classList.remove('is-hover');
}

/** 离开条带：全部收为细条（CSS transition 平滑回缩）。 */
function collapse(): void {
  clearHover();
  for (const it of allItems()) setGrow(it, 0);
}

function onMove(e: PointerEvent): void {
  // 第 19 轮：mousemove 合并到 rAF（每帧至多一次重算，不逐事件全量处理）
  moveX = e.clientX;
  moveY = e.clientY;
  if (moveQueued) return;
  moveQueued = true;
  requestAnimationFrame(() => {
    moveQueued = false;
    applyMove();
  });
}

function applyMove(): void {
  if (!mainEl || !track || !items.length) {
    collapse();
    return;
  }
  const m = mainEl.getBoundingClientRect();
  const x = moveX - m.left;
  const y = moveY - m.top;
  const inZone =
    railW > 0 &&
    x >= railX - 6 &&
    x <= railX + railW + 14 &&
    y >= railTop &&
    y <= railTop + railH;
  if (!inZone) {
    collapse();
    return;
  }
  const hitR = Math.max(pitch / 2, 8); // 压缩节距下保持 ≥8px 命中半径
  let best: RailItem | null = null;
  let bestD = Infinity;
  for (const it of allItems()) {
    if (!it.visible) continue; // 第 19 轮：仅对可见条（≤21 根含折叠条）计算权重
    const d = Math.abs(y - (railTop + it.y));
    setGrow(it, 1 - d / RANGE); // 变长 fisheye + 微亮（线性衰减，RANGE=100px 陡降）
    if (d < bestD) {
      bestD = d;
      best = it;
    }
  }
  const hit = best !== null && bestD <= hitR ? best : null;
  if (hit) {
    setGrow(hit, 1); // 吸附：最近者拉满（最长+全亮）
    if (hoverItem !== hit) {
      if (hoverTimer !== null) {
        window.clearTimeout(hoverTimer);
        hoverTimer = null;
      }
      removeCard();
      hoverItem = hit;
      hoverTimer = window.setTimeout(() => {
        hoverTimer = null;
        if (hoverItem) showCard(hoverItem);
      }, PREVIEW_MS);
    }
  } else {
    clearHover();
  }
  // 高亮类最后统一打（避免 clearHover 把新命中条的高亮抹掉）
  for (const it of allItems()) it.el.classList.toggle('is-hover', it === hit);
}

function onLeave(): void {
  collapse();
}

function onClick(e: MouseEvent): void {
  if (!mainEl || !hoverItem) return;
  const m = mainEl.getBoundingClientRect();
  const x = e.clientX - m.left;
  const y = e.clientY - m.top;
  if (x < railX - 6 || x > railX + railW + 14 || y < railTop || y > railTop + railH) return;
  if (Math.abs(y - (railTop + hoverItem.y)) > Math.max(pitch / 2, 8)) return;
  e.preventDefault();
  // 折叠条 → 定位到最早可见轮；普通条 → 定位到该轮起点（一问一答的第一条）
  hoverItem.startCol.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function onScroll(): void {
  if (modeAll) return;
  queueSync(); // 超长会话：滚动刷新「跟随可见区域」子集
}

// ---- 对外 API（messages.ts / main.ts 接线；main.ts 调用一次） --------------------

function queueSync(): void {
  if (syncQueued) return;
  syncQueued = true;
  requestAnimationFrame(() => {
    syncQueued = false;
    layout();
  });
}

/** 注册一根轮条（addUserMessage / ensureAssistant 调用；第 15 轮：一问一答合并）。
 *  user 消息 = 新轮起点；assistant 段合并进最近一轮（含流式未收尾），
 *  工具活动随其轮内不单独成条。孤立 assistant（恢复历史首条）自成一轮。 */
export function railAdd(col: HTMLElement, role: 'user' | 'assistant'): void {
  if (!ensureTrack() || !track) return;
  const last = items[items.length - 1];
  if (role === 'user' || !last) {
    const bar = document.createElement('div');
    bar.className = 'railv3-item' + (role === 'assistant' ? ' is-reply' : '');
    track.appendChild(bar);
    items.push({ startCol: col, cols: [col], hasReply: role === 'assistant', el: bar, y: 0, visible: false, fold: 0 });
  } else {
    // 合并进最近一轮（一问一答一根条）
    last.cols.push(col);
    if (!last.hasReply) {
      last.hasReply = true;
      last.el.classList.add('is-reply');
    }
  }
  layout();
}

/** 清空会话时调用：移除全部长条并复位交互状态（轨道元素常驻 #main）。 */
export function railReset(): void {
  items = [];
  foldItem = null;
  clearHover();
  if (track) track.textContent = '';
}

/** 聊天区重渲染后同步（流式钩子：重排 + 新增长条计数，rAF 节流）。 */
export function railSync(): void {
  queueSync();
}

/** 装配（幂等）。 */
export function initRail(): void {
  if (mainEl) return;
  mainEl = document.getElementById('main');
  msgsEl = document.getElementById('messages');
  if (!mainEl || !msgsEl) return;
  ensureTrack();
  layout();

  mainEl.addEventListener('pointermove', onMove);
  mainEl.addEventListener('pointerleave', onLeave);
  mainEl.addEventListener('click', onClick);
  msgsEl.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', queueSync);

  const ro = new ResizeObserver(queueSync);
  ro.observe(mainEl);
  ro.observe(msgsEl);
}

