// ============================================================================
// ui/restore.ts — 启动/切换会话时恢复活跃会话历史：
//   GET /api/sessions/{id}/messages → 用与 live 相同的渲染管线渲染最近
//   N=200 条存量（更早的加折叠提示）→ 尾部加「以下为本次会话」分隔线 →
//   之后的 SSE 增量照旧。衔接去重：SSE 重放的助手文本若与已恢复尾部同内容
//   （前缀匹配）则吞掉，直到发散；done 全量一致时丢弃重复气泡。
//   404/超时/端点缺失 → 保持空视图 + 轻提示，绝不崩溃。
// ============================================================================
import { api } from '../api';
import { S } from '../state';
import { el } from '../utils/dom';
import type { HistoryMsg } from '../types';
import {
  addUserMessage,
  autoscroll,
  ensureAssistant,
  finalizeAssistant,
  renderEmptyHint,
} from './messages';
import { railReset, railSync } from './rail';
import { buildToolCard, setToolResult, type ToolCardRef } from './toolcards';

const MAX_RESTORE = 200;

// ---- 衔接去重状态 ------------------------------------------------------------

/** 已恢复尾部的最后一条（user/assistant；tool 不参与去重）。 */
let tail: HistoryMsg | null = null;

let guardActive = false;   // 正在对 live 助手增量做前缀匹配
let guardBuf = '';         // 已吞入的增量
let guardAll = false;      // 缓冲恰好等于完整 tail 内容（可能整体重放）

/** 重置去重状态（清空会话后调用）。 */
export function resetRestore(): void {
  tail = null;
  guardActive = false;
  guardBuf = '';
  guardAll = false;
}

/**
 * 处理一条 live 助手文本增量：若与已恢复尾部前缀匹配则吞掉（返回 null），
 * 发散后一次性吐出累积缓冲并解除守卫。
 */
export function feedAssistantDelta(delta: string): string | null {
  if (tail?.role !== 'assistant') {
    tail = null;
    return delta === '' ? null : delta;
  }
  if (!guardActive) {
    guardActive = true;
    guardBuf = '';
    guardAll = false;
  }
  guardBuf += delta;
  const tc = tail.content ?? '';
  if (tc.startsWith(guardBuf)) {
    if (guardBuf === tc) guardAll = true;
    return null;
  }
  // 发散：吐出累积内容，退出守卫
  const out = guardBuf;
  guardActive = false;
  guardAll = false;
  tail = null;
  return out === '' ? null : out;
}

/**
 * done 事件钩子：若整条 live 助手消息是已恢复尾部的重放（无新增内容），
 * 返回 true 让调用方移除该重复气泡。
 */
export function finalAssistantDedup(text?: string): boolean {
  if (!guardActive) return false;
  guardActive = false;
  const drop =
    guardAll ||
    (typeof text === 'string' && text !== '' && tail?.role === 'assistant' && text === (tail.content ?? ''));
  guardAll = false;
  tail = null;
  return drop;
}

// ---- 渲染 ---------------------------------------------------------------------

// ---- 历史工具条目：结构化字段渲染（W252 契约，第 24 轮去兼容层） ----
// call: {role:"tool", kind:"call", tool_call_id, tool_name, tool_args}
// result: {role:"tool", kind:"result", tool_call_id, tool_value, tool_error}
// 按 tool_call_id 配对 call→result（顺序无关）；缺配对显示「（无结果记录）」；
// 孤立 result 以可见文本行展示，绝不静默丢失。
// 注：thinking / info 块为 SSE 专属，不落盘；恢复侧 thinking 条目按 W252 渲染。

let histToolStep = 0;
const toolCardsById = new Map<string, ToolCardRef>(); // 本会话渲染中的 call 卡

function toJsonText(v: unknown): string {
  if (typeof v === 'string') return v;
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return String(v);
  }
}

function appendToolLine(text: string, container: HTMLElement): void {
  const col = el('div', 'mcol');
  const msg = el('div', 'msg tool');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '工具'));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble');
  const body = el('div', 'content restore-tool');
  body.textContent = text;
  bubble.appendChild(body);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
}

/** 渲染一条结构化 tool 消息（call 建卡 / result 按 id 配对回填）。 */
function renderToolMessage(m: HistoryMsg, container: HTMLElement): void {
  if (m.kind === 'call') {
    histToolStep += 1;
    const id = m.tool_call_id ?? 'call_' + histToolStep;
    const ref = buildToolCard({
      step: histToolStep,
      name: m.tool_name ?? 'tool',
      argsText: toJsonText(m.tool_args),
    });
    container.appendChild(ref.col);
    toolCardsById.set(id, ref);
    autoscroll(true);
    return;
  }
  // result：按 tool_call_id 配对（与到达顺序无关）
  const id = m.tool_call_id ?? '';
  const ref = toolCardsById.get(id);
  if (ref) {
    const failed = !!m.tool_error && m.tool_error !== '';
    setToolResult(ref, failed ? String(m.tool_error) : toJsonText(m.tool_value), failed);
    toolCardsById.delete(id);
    autoscroll(true);
    return;
  }
  // 孤立 result（无对应 call）：可见文本行，不静默丢失
  appendToolLine(
    '工具结果（无对应调用记录）：' + (m.tool_error ? String(m.tool_error) : toJsonText(m.tool_value)),
    container,
  );
}

function renderOne(m: HistoryMsg, container: HTMLElement): void {
  const content = String(m.content ?? '');
  if (m.role === 'user') {
    addUserMessage(content, container);
    return;
  }
  if (m.role === 'assistant') {
    if (content.trim() === '') return; // 空内容不渲染空块
    // 与 live 相同的 marked 渲染管线（ensureAssistant → finalizeAssistant 冲刷）
    const a = ensureAssistant(container);
    a.text = content;
    finalizeAssistant(a);
    S.assistant = null;
    return;
  }
  if (m.role === 'thinking') {
    // W252：后端将持久化思考（role=thinking）；未就绪时不出现该条目。
    // 渲染为与 live 相同的弱化思考块样式（静态内容，标题行可折叠）。
    renderThinkingHistory(content, container);
    return;
  }
  renderToolMessage(m, container);
}

/** 历史思考条目：弱化块（.think-seg 样式，与 live 同款；折叠交互复用）。 */
function renderThinkingHistory(content: string, container: HTMLElement): void {
  const col = el('div', 'mcol');
  const msg = el('div', 'msg think-seg');
  const cap = el('div', 'msg-caption think-head');
  cap.appendChild(el('span', 'who', '思考'));
  const foldMark = el('span', 'think-fold-mark', '▾');
  cap.appendChild(foldMark);
  cap.appendChild(el('span', 'think-time', ''));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble think-seg-bubble');
  const body = el('div', 'think-seg-body');
  body.textContent = content;
  bubble.appendChild(body);
  const folded = el('div', 'think-seg-folded', '思考已折叠，点击展开');
  bubble.appendChild(folded);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
  cap.addEventListener('click', () => {
    col.classList.toggle('collapsed');
    foldMark.textContent = col.classList.contains('collapsed') ? '▸' : '▾';
  });
}

/**
 * 渲染指定会话历史（最近 200 条 + 折叠提示 + 「以下为本次会话」分隔线）。
 * 404/超时/端点缺失 → 空视图 + 轻提示，不崩溃。
 */
/**
 * 渲染指定会话历史（最近 200 条 + 折叠提示 + 「以下为本次会话」分隔线）。
 * 第 10 轮：离屏双缓冲——先在离屏容器完整构建，再一次性 replaceChildren，
 * 不出现「清空→空白→重建」帧；guard() 返回 false 时丢弃（竞态：旧请求
 * 结果晚到不得覆盖新会话）。404/超时/端点缺失 → 轻提示，不崩溃。
 */
function appendNote(text: string): void {
  const msgs = document.getElementById('messages');
  if (msgs && !msgs.querySelector('.restore-note')) {
    msgs.appendChild(el('div', 'restore-note', text));
  }
}

export async function restoreSessionHistory(id: string, guard?: () => boolean): Promise<void> {
  let resp;
  try {
    resp = await api.messages(id);
  } catch (err) {
    // 404/超时/端点缺失：保持现有视图，仅轻提示
    if (!S.streaming) {
      appendNote('历史恢复暂不可用（' + (err instanceof Error ? err.message : String(err)) + '）');
    }
    return;
  }
  if (guard && !guard()) return; // 竞态：期间已发起更新的切换，丢弃本次结果
  const all = resp.messages ?? [];
  if (S.streaming) return; // 已开跑：不打断实时流

  // 离屏构建（不挂载，浏览器不绘制中间态）
  railReset(); // 先清旧 rail 条目；离屏渲染注册的新条目在替换后重新 layout
  const off = document.createElement('div');
  if (all.length > MAX_RESTORE) {
    const fold = el('div', 'restore-fold', '更早的历史已折叠 · 仅显示最近 ' + MAX_RESTORE + ' 条');
    off.appendChild(fold);
  }
  const recent = all.length > MAX_RESTORE ? all.slice(all.length - MAX_RESTORE) : all;
  for (const m of recent) renderOne(m, off);
  if (toolCardsById.size) {
    // 无配对结果的调用：标记「（无结果记录）」（第 24 轮文案）
    for (const ref of toolCardsById.values()) {
      setToolResult(ref, '（无结果记录）', false);
    }
    toolCardsById.clear();
  }
  if (recent.length) {
    const sep = el('div', 'live-sep');
    sep.appendChild(el('span', null, '以下为本次会话'));
    sep.title = '上方为刷新前恢复的存量消息';
    off.appendChild(sep);
  }
  if (guard && !guard()) return;

  // 一次性替换（无空白帧）
  const msgs = document.getElementById('messages');
  if (!msgs) return;
  msgs.replaceChildren(...off.childNodes);
  if (!recent.length) {
    // 空会话：空态提示 + 「以下为本次会话」分隔线（第 12 轮：新会话切换可见）
    renderEmptyHint();
    const sep = el('div', 'live-sep');
    sep.appendChild(el('span', null, '以下为本次会话'));
    msgs.appendChild(sep);
  }
  railSync();
  autoscroll(true);
  tail = recent.length ? recent[recent.length - 1] ?? null : null;
}

/**
 * 解析当前活跃会话 id（W237）：
 *   1) GET /api/sessions 的 active 字段；2) GET /api/workspaces 的 active_session；
 *   3) 兜底：旧后端无 active 概念 → 若 cli-main 存在则用之；否则 null。
 */
export async function resolveActiveSession(): Promise<string | null> {
  try {
    const d = await api.sessions();
    const act = (d.sessions ?? []).find((s) => s.active === true);
    if (act?.id) return act.id;
  } catch {
    /* fall through */
  }
  try {
    const w = await api.workspaces();
    if (w.active_session) return w.active_session;
  } catch {
    /* fall through */
  }
  try {
    const d = await api.sessions();
    if ((d.sessions ?? []).some((s) => s.id === 'cli-main')) return 'cli-main';
  } catch {
    /* ignore */
  }
  return null;
}

/** 启动恢复：按当前活跃会话拉取历史（不再特设 cli-main）。 */
export async function restoreActiveHistory(): Promise<void> {
  const id = await resolveActiveSession();
  if (id === null) {
    if (!S.streaming) appendNote('未找到活跃会话 · 发送第一条消息后自动建立');
    return;
  }
  await restoreSessionHistory(id);
}

// ---- 会话切换（第 10 轮：无空白帧 + 竞态防护） ----

let switchSeq = 0;
let progressEl: HTMLElement | null = null;

function showSwitchProgress(): void {
  if (progressEl) return;
  progressEl = document.createElement('div');
  progressEl.className = 'switch-progress';
  progressEl.title = '正在加载会话历史…';
  document.body.appendChild(progressEl);
}

function hideSwitchProgress(): void {
  progressEl?.remove();
  progressEl = null;
}

/**
 * 激活会话后切换聊天区（第 10 轮）：
 *   - 不清空现有内容——历史在离屏构建完成后一次性替换（无空白帧）；
 *   - 加载期间仅显示顶部细进度条（轻量状态，不整页空白）；
 *   - seq 竞态防护：切换期间重复点击会发起更新的请求，旧请求结果
 *     （guard 不匹配）直接丢弃，不覆盖新会话。
 */
export function switchToSession(id: string): void {
  const seq = ++switchSeq;
  toolCardsById.clear();
  histToolStep = 0;
  S.assistant = null; // 旧流式视图随替换移除；新 turn 从新段开始
  S.turn = null;
  showSwitchProgress();
  void restoreSessionHistory(id, () => seq === switchSeq).finally(() => {
    if (seq === switchSeq) hideSwitchProgress();
  });
}

/** 会话切换是否进行中（供外部判断加载态）。 */
export function isSwitching(): boolean {
  return progressEl !== null;
}

// ============================================================================
// ui/toolcards.ts — 工具调用卡片（W239 任务 3+4 重写）：
//   任务4：工具事件按发生时间与 user/assistant 消息交错内联 —— 卡片不再
//          集中在助手气泡顶部区块，而是作为消息流级条目（.mcol.msg.tool）
//          按事件顺序插入 #messages（用户消息 → 工具调用+结果 → 助手回复）。
//   任务3：折叠态即显示粗略内容 —— summary 两行：
//          第1行 step · 工具名 · 状态；第2行 参数一行摘要（截断 ~60 字）；
//          结果到达后追加第3行 结果一行摘要（value 首行截断 ~60 字）。
//          展开（open）才见参数/结果全文（沿用 .tool-details 体系）。
// ============================================================================
import { el } from '../utils/dom';
import { autoscroll } from './messages';
import type { ToolPayload, ToolResultPayload } from '../types';

const SUMMARY_CHARS = 60; // 参数/结果摘要截断字数

/** 按工具调用 id 索引（跨消息流条目）。 */
const opIndex = new Map<string, ToolCardRef>();
let toolStep = 0;

/** 当前工具步骤数（供状态栏 step 显示）。 */
export function getToolStep(): number {
  return toolStep;
}

/** 清空会话/切换会话时复位（resetMessages 调用）。 */
export function resetToolCards(): void {
  opIndex.clear();
  toolStep = 0;
}

/**
 * W263：新一轮开始时把当前轮工具步数清零（每个 tool 事件 +1）。
 * 与 resetToolCards 的区别：只清计数器，保留 opIndex —— 迟到/跨轮到达的
 * tool_result 仍能按 id 回填到已渲染的卡片上。
 */
export function resetTurnStep(): void {
  toolStep = 0;
}

function toJsonText(v: unknown): string {
  if (typeof v === 'string') return v;
  try {
    return JSON.stringify(v);
  } catch {
    return String(v);
  }
}

function summaryOf(text: string): string {
  const t = text.replace(/\s+/g, ' ').trim();
  if (t.length <= SUMMARY_CHARS) return t;
  return t.slice(0, SUMMARY_CHARS) + '…';
}


/** 工具卡构建数据（live 事件与历史恢复共用）。 */
export interface ToolCardData {
  step: number;
  name: string;
  argsText: string; // 参数全文
}

/** 已构建的工具卡引用（供结果回填 / 复制）。 */
export interface ToolCardRef {
  col: HTMLElement;
  card: HTMLElement;
  label: HTMLElement;
  resultPv: HTMLElement;
  body: HTMLElement;
}

/** 构建工具调用卡片 DOM（消息流级条目；live 与恢复渲染共用同一款式）。 */
export function buildToolCard(d: ToolCardData): ToolCardRef {
  const col = el('div', 'mcol');
  const msg = el('div', 'msg tool');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '工具'));
  cap.appendChild(el('span', null, d.name));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble');
  const card = document.createElement('details');
  card.className = 'toolcard running';
  const head = document.createElement('summary');
  head.className = 'toolcard-head';
  head.setAttribute('aria-expanded', 'false');
  const row1 = el('div', 'toolcard-row1');
  row1.appendChild(el('span', 'step-tag', 'step ' + d.step));
  row1.appendChild(el('span', 'toolcard-name', d.name));
  const state = el('span', 'toolcard-state');
  state.innerHTML = '<span class="ts-dot"></span><span class="ts-label">运行中</span>';
  row1.appendChild(state);
  const copyBtn = el('button', 'toolcard-copy', '复制') as HTMLButtonElement;
  copyBtn.type = 'button';
  copyBtn.title = '复制参数与结果（JSON）';
  copyBtn.addEventListener('click', (e) => {
    e.preventDefault(); // 阻止 summary 切换展开
    e.stopPropagation();
    const outEl = card.querySelector<HTMLElement>('.tool-out');
    const text = d.argsText + '\n' + (outEl?.textContent ?? '');
    void navigator.clipboard.writeText(text).catch(() => {
      /* clipboard unavailable */
    });
  });
  row1.appendChild(copyBtn);
  head.appendChild(row1);
  const argsPv = el('div', 'toolcard-args-preview');
  const a = summaryOf(d.argsText);
  argsPv.textContent = a ? '参数：' + a : '参数：—';
  head.appendChild(argsPv);
  const resultPv = el('div', 'toolcard-result-preview');
  resultPv.textContent = '';
  head.appendChild(resultPv);
  card.appendChild(head);
  // 展开后可见：参数全文（平铺，无需二级展开）
  const body = el('div', 'toolcard-body');
  body.appendChild(el('div', 'tool-args', d.argsText));
  card.appendChild(body);
  // 整卡单击展开/收起详情：同步 aria-expanded
  card.addEventListener('toggle', () => {
    head.setAttribute('aria-expanded', card.open ? 'true' : 'false');
  });
  bubble.appendChild(card);
  msg.appendChild(bubble);
  col.appendChild(msg);
  return {
    col,
    card,
    label: state.querySelector<HTMLElement>('.ts-label') ?? state,
    resultPv,
    body,
  };
}

/** 回填工具结果（结果预览行 + 展开区全文 + 完成/失败态）。 */
export function setToolResult(ref: ToolCardRef, resultText: string, failed: boolean): void {
  ref.card.classList.remove('running');
  ref.card.classList.add(failed ? 'err' : 'ok');
  ref.label.textContent = failed ? '失败' : '完成';
  const r = summaryOf(resultText);
  ref.resultPv.textContent = r ? '结果：' + r : '';
  if (r) ref.resultPv.classList.add('has');
  if (!ref.body.querySelector('.tool-out')) {
    ref.body.appendChild(el('div', 'tool-out' + (failed ? ' err-c' : ''), resultText));
  }
}

/** 新建工具调用卡片（live 事件；按事件时间插入消息流尾部）。 */
export function pushToolCard(p: ToolPayload): HTMLElement {
  toolStep += 1;
  const ref = buildToolCard({ step: toolStep, name: String(p.name || 'tool'), argsText: toJsonText(p.args) });
  const MsgsEl = document.getElementById('messages');
  if (MsgsEl) MsgsEl.appendChild(ref.col);
  autoscroll();
  opIndex.set(String(p.id), ref);
  return ref.col;
}

/** 应用工具结果：状态/结果摘要/结果全文（按 id 索引）。 */
export function applyToolResult(p: ToolResultPayload): void {
  const rec = opIndex.get(String(p.id));
  if (!rec) return;
  const failed = p.ok === false || !!p.error;
  const label = failed
    ? '失败'
    : p.decision === 'deny'
      ? '拒绝'
      : p.decision === 'ask'
        ? '待确认'
        : '完成';
  setToolResult(rec, p.error ? String(p.error) : toJsonText(p.value), failed || p.decision === 'deny');
  rec.label.textContent = label;
  autoscroll();
}

// ============================================================================
// state.ts — 状态层（单一职责）：当前 turn 的全局 UI 状态，纯数据、无 DOM。
// 视图句柄（AssistantView 等）在 ui/view.ts；布局状态在 ui/sidebar.ts 内部。
// ============================================================================
import type { ConnState, SessionInfo } from './types';
import type { AssistantView } from './ui/view';

export interface AppState {
  /** current turn id (null when idle) */
  turn: number | null;
  streaming: boolean;
  /** turn start timestamp for the elapsed timer */
  t0: number;
  conn: ConnState;
  assistant: AssistantView | null;
  sessions: SessionInfo[];
  selSession: string | null;
  /** elapsed-seconds timer for the bottom statusbar */
  msgTimer: number | null;
}

export const S: AppState = {
  turn: null,
  streaming: false,
  t0: 0,
  conn: 'connecting',
  assistant: null,
  sessions: [],
  selSession: null,
  msgTimer: null,
};

// ============================================================================
// DOM helpers + formatting utilities
// ============================================================================

/** querySelector with element type; null when absent. */
export function $<T extends Element = Element>(sel: string, root: ParentNode = document): T | null {
  return root.querySelector<T>(sel);
}

/** querySelectorAll, returned as an array. */
export function $$<T extends Element = Element>(sel: string, root: ParentNode = document): T[] {
  return Array.from(root.querySelectorAll<T>(sel));
}

/** querySelector that throws when the anchor element is missing. */
export function need<T extends Element = Element>(sel: string, root: ParentNode = document): T {
  const n = $<T>(sel, root);
  if (!n) throw new Error('missing element: ' + sel);
  return n;
}

const ESC_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

/** HTML-escape an arbitrary value. */
export function esc(s: unknown): string {
  return String(s).replace(/[&<>"']/g, (c) => ESC_MAP[c] ?? c);
}

/** Create an element with optional class list and plain-text content. */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string | null,
  text?: unknown,
): HTMLElementTagNameMap[K] {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined && text !== null) n.textContent = String(text);
  return n;
}

/** mm:ss from a seconds value. */
export function fmtTime(sec: number): string {
  const t = Math.max(0, Math.floor(sec || 0));
  const m = Math.floor(t / 60);
  const s = t % 60;
  return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

/** hh:mm:ss of now. */
export function fmtNow(): string {
  const d = new Date();
  const p = (n: number) => (n < 10 ? '0' : '') + n;
  return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds());
}

const fmtDigits = (v: number, digits: number) => {
  const s = v.toFixed(digits);
  return s.endsWith('.0') ? s.slice(0, -2) : s;
};

/** Compact number: 1234 -> '1.2K', 1000000 -> '1M'; '—' for empty/invalid. */
export function fmtCompact(n: number | null | undefined, digits = 1): string {
  if (n === undefined || n === null || !Number.isFinite(n)) return '—';
  const abs = Math.abs(n);
  if (abs >= 1e9) return fmtDigits(n / 1e9, digits) + 'B';
  if (abs >= 1e6) return fmtDigits(n / 1e6, digits) + 'M';
  if (abs >= 1e3) return fmtDigits(n / 1e3, digits) + 'K';
  return String(Math.round(n));
}

