      'err',
      8_000,
    );
  } finally {
    compacting = false;
  }
}

// ---- send / cancel -------------------------------------------------------------

/**
 * 取消当前轮次（单一取消入口）：#btnCancel 与 statusline 的 #slStop 共用。
 * 逻辑不变：非运行中直接忽略 → 状态栏「取消中…」→ POST /api/cancel，
 * 失败只提示错误，本地状态交由 SSE 的 status:cancelled 收尾（finalizeTurn）。
 */
export function requestCancel(): void {
  if (!S.streaming) return;
  setStatus('取消中…', 'busy');
  void api.cancel().catch((err: unknown) => {
    setStatus('取消失败：' + (err instanceof Error ? err.message : String(err)), 'err');
  });
}

export function initChat(): void {
