// ============================================================================
// utils/markdown.ts — 增量流式 markdown 渲染（W301）
//
// 现状问题（messages.ts 旧实现）：每个渲染节拍对「整段累积文本」全量
//   marked.parse + 全量代码高亮。实测 128K 字符时单次 ≈ 70ms（不含 DOM
//   解析/布局/绘制/强制回流），60ms 节拍被吃满 → 主线程饱和、UI 假死。
//
// 本模块把文本切成两段：
//   - stableHtml：已固化前缀的 HTML（只解析一次，之后永不重解析）
//   - stableLen ：该前缀在原文中的长度
//   - tail      ：未固化尾部（每个节拍只解析这一段）
// update(fullText) 返回 stableHtml + md(tail)，在「安全切分」前提下与
// 「整段一次解析」的 HTML 等价（见 bench --verify 的实测比对）。
//
// 切分必须保守：宁可少固化（退化为当前全量行为，不得比现状更差），
// 也绝不固化错。安全边界判定见 blockSafe()：
//   1) 只在「空行边界」后固化完整块（围栏内/HTML 容器块内的空行不算边界）；
//   2) 未闭合围栏、未闭合 HTML 容器（pre/script/style/textarea/注释）不固化；
//   3) 可能被后续文本改变语义的块不固化：引用式链接 [x] / [x][y]、文末引用
//      定义、表格行（可能成为表头）、后一块以缩进开头（列表/引用/缩进代码
//      可跨空行续接）、同类型列表项相邻（会被合并成一个列表）；
//   4) 块内行内标记未闭合（** / ` / ~~ / 方括号）不固化。
// ============================================================================
import { marked } from 'marked';

// 与现状一致（messages.ts 同样设置；两边同值，重复设置无害）
marked.setOptions({ breaks: true, gfm: true });

// ---- 兜底转义（与 utils/dom.esc 同一映射；本地实现以免本模块依赖 DOM） -------
const ESC_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ESC_MAP[c] ?? c);
}

/** 一次性全量渲染（历史恢复路径 / done 全文覆盖用）。 */
export function renderMarkdown(text: string): string {
  try {
    return marked.parse(text, { async: false }) as string;
  } catch {
    return '<pre>' + escapeHtml(text) + '</pre>';
  }
}

/** 单块解析（与 renderMarkdown 同管线；固化块逐段解析用）。 */
function md(text: string): string {
  return renderMarkdown(text);
}

// ---- 边界判定 ----------------------------------------------------------------

/** 围栏行：0-3 空格缩进 + 3 个以上反引号/波浪号（可带语言行）。 */
const FENCE_RE = /^ {0,3}(`{3,}|~{3,})(.*)$/;
/** 列表项行（无序 / 有序）。 */
const LIST_RE = /^ {0,3}(?:[-*+]|\d{1,9}[.)])(?:[ \t]|$)/;
/** 缩进行（2 空格以上或制表符）：列表/引用续行、缩进代码块可跨空行。 */
const INDENT_RE = /^(?: {2,}|\t)/;
/** setext 标题下划线（空行理论上阻断，保守起见仍不固化）。 */
const SETEXT_RE = /^ {0,3}(?:=+|-+)[ \t]*$/;
/** 主题分隔线（`***` 等，行内标记统计前剔除，避免误判未闭合 `**`）。 */
const THEMATIC_RE = /^ {0,3}(?:(?:\*[ \t]*){3,}|(?:-[ \t]*){3,}|(?:_[ \t]*){3,})$/;
/** 引用定义行：`[id]: url`（可出现在文末，改变前文引用式链接的解析结果）。 */
const REF_DEF_RE = /^ {0,3}\[[^\]\n]+\]:/m;
/** 引用式链接用法：`[text]` 或 `[text][ref]`（未紧跟 `(` 即非行内链接）。 */
const REF_USE_RE = /\[[^\]\n]*\](?!\()/;
/** 可跨空行的 HTML 容器块。 */
const HTML_OPEN_RE = /<(pre|script|style|textarea)\b/i;
const HTML_CLOSE_RE = /<\/(pre|script|style|textarea)\s*>/i;
const COMMENT_OPEN_RE = /<!--/;
const COMMENT_CLOSE_RE = /-->/;

/** 块内行内标记是否闭合（保守：统计为奇数即视为未闭合）。 */
function inlineBalanced(block: string): boolean {
  // 剔除围栏块内容 / 缩进代码 / 主题分隔线：其中的标记是字面量，不参与配对
  let inFence = false;
  let text = '';
  for (const line of block.split('\n')) {
    const fm = FENCE_RE.exec(line);
    if (fm) {
      inFence = !inFence;
      continue;
    }
    if (inFence) continue;
    if (THEMATIC_RE.test(line)) continue;
    if (/^(?: {4,}|\t)/.test(line)) continue;
    text += line + '\n';
  }
  if (inFence) return false; // 围栏未闭合
  const ticks = text.match(/`+/g);
  if (ticks && ticks.length % 2 !== 0) return false;
  const strong = text.match(/\*\*/g);
  if (strong && strong.length % 2 !== 0) return false;
  const strike = text.match(/~~/g);
  if (strike && strike.length % 2 !== 0) return false;
  const open = text.match(/\[/g);
  const close = text.match(/\]/g);
  if ((open?.length ?? 0) !== (close?.length ?? 0)) return false;
  return true;
}

function lastNonEmptyLine(text: string): string | null {
  const lines = text.split('\n');
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const l = lines[i];
    if (l !== undefined && l.trim() !== '') return l;
  }
  return null;
}

function firstNonEmptyLine(text: string): string | null {
  for (const l of text.split('\n')) {
    if (l.trim() !== '') return l;
  }
  return null;
}

/**
 * 判断 [块] 能否在「其后空行边界」处固化（rest = 边界之后的全部剩余文本）。
 * 返回 false 时 stableLen 不前进（该块继续留在 tail 里逐节拍重解析）。
 */
function blockSafe(block: string, rest: string): boolean {
  // 1) 可跨空行的 HTML 容器 / 注释未闭合
  if (HTML_OPEN_RE.test(block) && !HTML_CLOSE_RE.test(block)) return false;
  if (COMMENT_OPEN_RE.test(block) && !COMMENT_CLOSE_RE.test(block)) return false;
  // 2) 引用式链接：块内用法依赖文末引用定义 → 语义可能被后文改变
  if (REF_USE_RE.test(block)) return false;
  if (REF_DEF_RE.test(rest)) return false;
  // 3) 块内行内标记未闭合
  if (!inlineBalanced(block)) return false;
  const last = lastNonEmptyLine(block);
  const next = firstNonEmptyLine(rest);
  // 4) 块末行含 `|`：可能成为表格表头（后续分隔行会改变整块语义）
  if (last !== null && last.indexOf('|') !== -1) return false;
  if (next === null) return true;
  // 5) 后一块续接本块：同类型列表项会合并；缩进行会续接列表/引用/缩进代码
  if (last !== null && LIST_RE.test(last) && LIST_RE.test(next)) return false;
  if (INDENT_RE.test(next)) return false;
  if (SETEXT_RE.test(next)) return false;
  return true;
}

/**
 * 在 tail 中寻找可安全固化的前缀长度（0 = 不前进，退化为全量）。
 * 扫描到第一个不安全边界即停止：不越过未确定块固化其后内容。
 */
function findFixLen(tail: string): number {
  let i = 0; // 当前行起点
  let stable = 0; // 已确认可固化的长度
  let fenceChar = ''; // 未闭合围栏字符（'' = 不在围栏内）
  let fenceLen = 0;
  while (i < tail.length) {
    const nl = tail.indexOf('\n', i);
    const lineEnd = nl === -1 ? tail.length : nl;
    const line = tail.slice(i, lineEnd);
    const fm = FENCE_RE.exec(line);
    if (fm) {
      const marker = fm[1] ?? '';
      const info = fm[2] ?? '';
      const ch = marker.charAt(0);
      if (fenceChar === '') {
        fenceChar = ch;
        fenceLen = marker.length;
      } else if (ch === fenceChar && marker.length >= fenceLen && info.trim() === '') {
        fenceChar = '';
        fenceLen = 0;
      }
      i = nl === -1 ? tail.length : nl + 1;
      continue;
    }
    // 空行 = 块边界（围栏内的空行不算）
    if (fenceChar === '' && line.trim() === '' && nl !== -1) {
      const cut = nl + 1; // 固化到该空行（含换行）
      const block = tail.slice(stable, cut);
      const rest = tail.slice(cut);
      if (block.trim() === '') {
        // 连续空行：直接并入已固化区（无内容可解析）
        stable = cut;
        i = cut;
        continue;
      }
      if (!blockSafe(block, rest)) break; // 不安全 → 停止固化，剩余全部走 tail
      stable = cut;
      i = cut;
      continue;
    }
    i = nl === -1 ? tail.length : nl + 1;
  }
  return stable;
}

// ---- 增量流式解析器 -----------------------------------------------------------

/**
 * 增量流式 markdown 解析器。
 * 每 tick 用「累积全文」调用 update()，返回该渲染的完整 HTML。
 */
export class MarkdownStream {
  /** 已固化前缀对应的 HTML */
  private stableHtml = '';
  /** stableHtml 对应的原文长度 */
  private stableLen = 0;
  /** 上一次 update() 传入的全文（用于前缀/回退判定与无变化短路） */
  private raw = '';
  /** 上一次的完整 HTML（内容未变时直接返回） */
  private html = '';

  /** 已固化前缀长度（诊断/基准用；只读）。 */
  get stableLength(): number {
    return this.stableLen;
  }

  /** 会话清空 / 新段开始时复位缓存。 */
  reset(): void {
    this.stableHtml = '';
    this.stableLen = 0;
    this.raw = '';
    this.html = '';
  }

  /** 每 tick 用「累积全文」调用；返回该渲染的完整 HTML。 */
  update(fullText: string): string {
    const text = typeof fullText === 'string' ? fullText : String(fullText ?? '');
    if (text === this.raw) return this.html; // 内容未变：不重复解析
    // 长度回退 / 内容不一致（done 全文覆盖、会话切换、编辑）→ 整体重来
    if (!text.startsWith(this.raw)) this.reset();

    const tail = text.slice(this.stableLen);
    const fix = findFixLen(tail);
    if (fix > 0) {
      const block = tail.slice(0, fix);
      try {
        this.stableHtml += md(block);
      } catch {
        // md() 自带兜底；此处仅防御
        this.stableHtml += '<pre>' + escapeHtml(block) + '</pre>';
      }
      this.stableLen += fix;
    }

    const rest = text.slice(this.stableLen);
    this.raw = text;
    this.html = this.stableHtml + md(rest);
    return this.html;
  }
}

// ============================================================================
// Code highlighting — highlight.js core + a lean registered language set
// (token colors come from theme CSS via .hljs-* classes)
//
// W301：增加内容键缓存（key = lang + '\0' + code 文本）+ 有界 LRU：
//   流式渲染每个节拍都会重建正文 innerHTML，`dataset.hlDone` 随之失效，
//   导致每个代码块每帧全量重高亮（128K 文本 ≈ 43 块 ≈ 70ms/帧）。
//   缓存命中时直接写回 HTML，未命中才调 hljs；超大单块（>32KB）跳过。
// ============================================================================
import hljs from 'highlight.js/lib/core';
import bash from 'highlight.js/lib/languages/bash';
import cpp from 'highlight.js/lib/languages/cpp';
import css from 'highlight.js/lib/languages/css';
import go from 'highlight.js/lib/languages/go';
import java from 'highlight.js/lib/languages/java';
import javascript from 'highlight.js/lib/languages/javascript';
import json from 'highlight.js/lib/languages/json';
import markdown from 'highlight.js/lib/languages/markdown';
import python from 'highlight.js/lib/languages/python';
import rust from 'highlight.js/lib/languages/rust';
import sql from 'highlight.js/lib/languages/sql';
import typescript from 'highlight.js/lib/languages/typescript';
import xml from 'highlight.js/lib/languages/xml';
import yaml from 'highlight.js/lib/languages/yaml';

hljs.registerLanguage('bash', bash);
hljs.registerLanguage('cpp', cpp);
hljs.registerLanguage('css', css);
hljs.registerLanguage('go', go);
hljs.registerLanguage('java', java);
hljs.registerLanguage('javascript', javascript);
hljs.registerLanguage('js', javascript);
hljs.registerLanguage('json', json);
hljs.registerLanguage('markdown', markdown);
hljs.registerLanguage('python', python);
hljs.registerLanguage('rust', rust);
hljs.registerLanguage('sql', sql);
hljs.registerLanguage('typescript', typescript);
hljs.registerLanguage('xml', xml);
hljs.registerLanguage('yaml', yaml);

// ---- 高亮结果缓存（有界 LRU） -------------------------------------------------

/** 缓存条目：高亮后的 innerHTML + 与 hljs.highlightElement 产出等价的 class。 */
interface HlEntry {
  html: string;
  cls: string;
  /** 估算占用（UTF-16 字符数 × 2 字节） */
  bytes: number;
}

const HL_MAX_ENTRIES = 128;                    // 条目上限
const HL_MAX_BYTES = 2 * 1024 * 1024;          // 总字节上限 2MB
const HL_MAX_BLOCK_CHARS = 32 * 1024;          // 单块源码 >32KB → 跳过高亮

const hlCache = new Map<string, HlEntry>();    // Map 迭代序 = LRU 序（旧 → 新）
let hlCacheBytes = 0;

/** 命中即视为最近使用（移到队尾）。 */
function cacheGet(key: string): HlEntry | undefined {
  const e = hlCache.get(key);
  if (e === undefined) return undefined;
  hlCache.delete(key);
  hlCache.set(key, e);
  return e;
}

/** 写入缓存并按 LRU 淘汰到上限内。 */
function cacheSet(key: string, html: string, cls: string): void {
  const bytes = (key.length + html.length + cls.length) * 2;
  if (bytes > HL_MAX_BYTES) return; // 单条已超总上限：不缓存（仍可用）
  const prev = hlCache.get(key);
  if (prev) hlCacheBytes -= prev.bytes;
  hlCache.set(key, { html, cls, bytes });
  hlCacheBytes += bytes;
  while (hlCache.size > HL_MAX_ENTRIES || hlCacheBytes > HL_MAX_BYTES) {
    const oldest = hlCache.keys().next();
    if (oldest.done === true) break;
    const e = hlCache.get(oldest.value);
    if (e) hlCacheBytes -= e.bytes;
    hlCache.delete(oldest.value);
  }
}

/** 从 class 里取 language-xxx 的语言名（无则空串）。 */
function langOf(block: HTMLElement): string {
  const m = /(?:^|\s)language-([\w-]+)/.exec(block.className);
  return m?.[1] ?? '';
}

/** Highlight every not-yet-processed <pre><code> inside a container. */
export function highlightCode(container: Element): void {
  const blocks = Array.from(container.querySelectorAll<HTMLElement>('pre code'));
  for (const block of blocks) {
    if (block.dataset.hlDone === '1') continue;
    const code = block.textContent ?? '';
    // 超大单块：跳过高亮（language-plaintext），避免单块拖垮主线程
    if (code.length > HL_MAX_BLOCK_CHARS) {
      if (block.className.indexOf('language-') === -1) block.className += ' language-plaintext';
      block.dataset.hlDone = '1';
      continue;
    }
    const key = langOf(block) + '\u0000' + code;
    const hit = cacheGet(key);
    if (hit) {
      // 命中：直接写回缓存 HTML + class（与 hljs.highlightElement 产出等价）
      block.innerHTML = hit.html;
      block.className = hit.cls;
      block.dataset.hlDone = '1';
      continue;
    }
    if (block.className.indexOf('language-') === -1) block.className += ' language-plaintext';
    try {
      hljs.highlightElement(block);
      block.dataset.hlDone = '1';
      cacheSet(key, block.innerHTML, block.className);
    } catch {
      /* unknown language → plain text */
    }
  }
}

