// ============================================================================
// ui/messages.ts — 消息流（单一职责，W240 连续事件流重构）：
//   一轮 = 按事件真实时间顺序渲染成一条连续流：
//     用户消息 → 思考段（弱化块，按序）→ 文本段（markdown 气泡）→
//     工具调用卡（内联条目）→ 工具结果 → 继续文本段 → ……
//   文本增量按节拍重渲染；工具事件到达时当前文本段收尾（flushTextSegment），
//   后续文本开启新段 —— 不再按"思考/文本/工具"分区聚合。
//   thinking 弱化为独立信息块按序出现；context/status 类事件渲染为信息块。
//   W301：文本段改用 MarkdownStream 增量渲染（只解析未固化尾部），
//   不再每个节拍对整段累积文本全量 marked.parse。
// ============================================================================
import { $, el, fmtNow, need } from '../utils/dom';
import { highlightCode } from '../utils/hljs';
import { MarkdownStream, renderMarkdown } from '../utils/markdown';
import type { AssistantView } from './view';
import { S } from '../state';
import { railAdd, railReset, railSync } from './rail';
import { resetToolCards } from './toolcards';

const MsgsEl = need<HTMLElement>('#messages');

// ---- markdown ---------------------------------------------------------------
/** Render markdown to safe-enough HTML（历史恢复/一次性渲染路径）。 */
export function md(text: string): string {
  return renderMarkdown(text);
}

// ---- 文本段增量渲染器（W301） ---------------------------------------------------
/**
 * 每个 AssistantView 一份流式渲染状态（WeakMap 挂载，不改 view.ts 公共接口；
 * 视图被回收后随 WeakMap 自动释放）：
 *   - stream       ：MarkdownStream（只解析未固化尾部）
 *   - stableNodes  ：已固化块对应的 DOM 节点（原地保留：不重解析、不重高亮）
 *   - tailNodes    ：未固化尾部节点（每 tick 用新节点替换）
 *   - lastText     ：上一次渲染的原文（内容未变直接跳过）
 */
interface StreamDom {
  stream: MarkdownStream;
  stableNodes: Node[];
  tailNodes: Node[];
  lastText: string;
  /** 是否已在 content 中建立过节点（false → 本次走整体构建） */
  inited: boolean;
}

const doms = new WeakMap<AssistantView, StreamDom>();

function domOf(view: AssistantView): StreamDom {
  let d = doms.get(view);
  if (!d) {
    d = {
      stream: new MarkdownStream(),
      stableNodes: [],
      tailNodes: [],
      lastText: '\u0000',
      inited: false,
    };
    doms.set(view, d);
  }
  return d;
}

/** 离屏解析 HTML 片段为节点数组（不挂载；供单次替换用）。 */
function htmlToNodes(html: string): Node[] {
  if (!html) return [];
  const off = document.createElement('div');
  off.innerHTML = html;
  return Array.from(off.childNodes);
}

// ---- scrolling ----------------------------------------------------------------
/** 粘性自动滚动：仅在用户接近底部时跟随；force 用于完成/新消息时。 */
export function autoscroll(force = false): void {
  const nearBottom = MsgsEl.scrollTop + MsgsEl.clientHeight >= MsgsEl.scrollHeight - 200;
  if (force || nearBottom) MsgsEl.scrollTop = MsgsEl.scrollHeight;
}

export function hideEmptyHint(): void {
  const hint = $('#emptyHint');
  if (hint) hint.classList.add('hidden');
}

/** Rebuild the empty state exactly as it shipped in index.html. */
export function renderEmptyHint(): void {
  MsgsEl.innerHTML = '';
  const hint = el('div', 'empty-hint empty-hint-fresh');
  hint.id = 'emptyHint';
  hint.appendChild(el('div', 'empty-mark', '◇'));
  hint.appendChild(el('div', 'empty-title', 'Celestea Studio'));
  hint.appendChild(el('div', 'empty-sub', '在下方输入消息开始对话 · Enter 发送 · Shift+Enter 换行'));
  MsgsEl.appendChild(hint);
}

/** 助手文本段是否已有内容（占位判定）。 */
export function assistantHasContent(view: AssistantView): boolean {
  return view.text.trim() !== '' || view.content.childElementCount > 0;
}

/** 直接移除空占位助手气泡（不渲染空块）。 */
export function removeAssistant(view: AssistantView): void {
  view.root.remove();
  doms.delete(view);
  S.assistant = null;
}

/** 清空消息流并重建空态（/api/clear 成功后调用；同时重置流式状态）。 */
export function resetMessages(): void {
  if (renderTimer !== null) {
    window.clearTimeout(renderTimer);
    renderTimer = null;
  }
  if (S.assistant) doms.delete(S.assistant);
  S.assistant = null;
  S.turn = null;
  thinkSeg = null;
  lastTextCol = null;
  resetToolCards(); // 工具卡片（消息流级条目）复位
  railReset(); // 消息 rail 复位
  renderEmptyHint();
}

// ---- 流式正文渲染节流 ---------------------------------------------------------
const RENDER_INTERVAL = 60; // ms —— 重渲染节拍（兼顾流畅与 CPU）
let renderTimer: number | null = null;
let renderDeadline = 0;

/**
 * 增量渲染文本段（W301）：
 *   1) MarkdownStream 只解析「未固化尾部」，返回 stableHtml / tailHtml 分解；
 *   2) 新固化的块（stableDeltaHtml）离屏构建后 append 到 content（已有块 DOM
 *      原地保留 → 不重解析、已高亮代码块不重建）；
 *   3) 尾部节点离屏构建后**单次替换**（insertBefore 新节点 + 移除旧节点，
 *      同一帧内完成，无空白帧；稳定块完全不动）；
 *   4) 仅在整体重置（done 全文覆盖 / 长度回退）时重建整个 content。
 */
function renderTextView(view: AssistantView): void {
  const d = domOf(view);
  if (d.lastText === view.text) {
    autoscroll();
    railSync();
    return;
  }
  const parts = d.stream.updateParts(view.text);
  d.lastText = view.text;

  if (parts.reset || !d.inited) {
    // 整体（重）构建：离屏解析后一次性 replaceChildren
    d.stableNodes = htmlToNodes(parts.stableHtml);
    d.tailNodes = htmlToNodes(parts.tailHtml);
    view.content.replaceChildren(...d.stableNodes, ...d.tailNodes);
    d.inited = true;
  } else {
    // 顺序：已固化块（旧）→ 本次新固化块 → 新尾部节点 → 移除旧尾部节点。
    // 新节点全部插在「旧尾部第一个节点」之前，插完再删旧尾部：同一帧内完成，
    // 旧内容在替换前始终可见（无空白帧），已固化块 DOM 完全不动。
    const anchor = d.tailNodes[0] ?? null;
    const place = (n: Node) => {
      if (anchor) view.content.insertBefore(n, anchor);
      else view.content.appendChild(n);
    };
    if (parts.stableDeltaHtml) {
      for (const n of htmlToNodes(parts.stableDeltaHtml)) {
        place(n);
        d.stableNodes.push(n);
      }
    }
    const freshTail = htmlToNodes(parts.tailHtml);
    for (const n of freshTail) place(n);
    for (const n of d.tailNodes) n.parentNode?.removeChild(n);
    d.tailNodes = freshTail;
  }

  highlightCode(view.content);
  autoscroll();
  railSync();
}

function scheduleTextView(view: AssistantView): void {
  if (renderTimer !== null) return; // 已有一次节拍排队
  const wait = Math.max(0, renderDeadline + RENDER_INTERVAL - performance.now());
  renderTimer = window.setTimeout(() => {
    renderTimer = null;
    renderDeadline = performance.now();
    renderTextView(view);
  }, wait);
}

/** 立即冲刷（turn 结束 / done 事件 / 最终文本到来时调用）。 */
function flushTextView(view: AssistantView): void {
  if (renderTimer !== null) {
    window.clearTimeout(renderTimer);
    renderTimer = null;
  }
  renderDeadline = performance.now();
  renderTextView(view);
}

/** 增量追加正文 delta（节拍渲染，不逐字重排）。 */
export function appendText(view: AssistantView, delta: string): void {
  view.text += delta || '';
  scheduleTextView(view);
}

/** Sync final assistant text from the done event. */
export function applyFinalText(view: AssistantView, text: string): void {
  if (typeof text !== 'string' || !text || view.text === text) return;
  view.text = text;
  // done 全文可能经引擎侧规范化，与流式累积不同（非前缀）→ MarkdownStream.update()
  // 检测到非前缀/长度回退会自行 reset 并全量渲染；若恰为前缀扩展则继续增量。
  flushTextView(view);
}

/** 冻结当前文本段：有内容则收尾为完整气泡，并解除当前段（工具事件/新段前调用）。 */
export function flushTextSegment(): void {
  if (S.assistant) {
    const a = S.assistant;
    S.assistant = null;
    if (assistantHasContent(a)) {
      a.bubble.classList.remove('streaming');
      a.bubble.classList.add('complete');
      flushTextView(a);
      autoscroll(true);
    } else {
      a.root.remove(); // 空占位不渲染
      doms.delete(a);
    }
  }
}

// ---- thinking（弱化独立段，按事件顺序出现，不再聚合进气泡） ----------------------

interface ThinkSeg {
  root: HTMLElement;   // .mcol 根（含折叠状态 class）
  head: HTMLElement;   // 标题行（可点折叠/展开）
  body: HTMLElement;   // 内容
  text: string;
}

let thinkSeg: ThinkSeg | null = null;
/**
 * 同轮最近文本段（含已被工具事件截断收尾的）：thinking 重排的目标锚点。
 * 工具截断场景下 S.assistant 已置空，但思考块仍须位于对应文本块上方。
 */
let lastTextCol: HTMLElement | null = null;

/** 轮次结束/新轮开始：清除思考段归属与文本段锚点（跨轮不跨移；DOM 保留）。 */
export function endTurn(): void {
  thinkSeg = null;
  lastTextCol = null;
}

/** Append a thinking delta（弱化块：左侧色条 + 浅色底 + 小字；独立成段）。
 * 第 22 轮重排规则收紧（任何到达顺序下成立）：
 *   思考块的目标位置 = 同轮最近文本块的正上方（紧贴）。目标 = 当前流式
 *   文本段（S.assistant.root）若存在，否则为 lastTextCol（同轮最近、含被
 *   tool 截断收尾的文本段）。若思考块当前位于目标之后（无论中间隔着
 *   工具卡/信息块等任何段落）→ insertBefore 局部前移到目标正上方；
 *   已在目标之前 → 不动。跨轮：endTurn() 清 thinkSeg/lastTextCol，绝不串位。
 */
export function appendThinking(delta: string): void {
  if (!thinkSeg) {
    hideEmptyHint();
    const root = el('div', 'mcol');
    const msg = el('div', 'msg think-seg');
    const cap = el('div', 'msg-caption think-head') as HTMLElement;
    cap.appendChild(el('span', 'who', '思考'));
    const foldMark = el('span', 'think-fold-mark', '▾');
    cap.appendChild(foldMark);
    cap.appendChild(el('span', 'think-time', fmtNow()));
    msg.appendChild(cap);
    const bubble = el('div', 'bubble think-seg-bubble');
    const body = el('div', 'think-seg-body');
    bubble.appendChild(body);
    const folded = el('div', 'think-seg-folded', '思考已折叠，点击展开');
    bubble.appendChild(folded);
    msg.appendChild(bubble);
    root.appendChild(msg);
    MsgsEl.appendChild(root);
    thinkSeg = { root, head: cap, body, text: '' };
    body.textContent = '思考中…'; // 流式思考占位态（弱化）
    // 点击标题行折叠/展开（第 23 轮：流式思考中不折叠）
    cap.addEventListener('click', () => {
      if (thinkSeg !== null && S.streaming) return; // 流式思考中不折叠
      root.classList.toggle('collapsed');
      foldMark.textContent = root.classList.contains('collapsed') ? '▸' : '▾';
    });
  }
  // 重排：目标 = 当前文本段 ?? 同轮最近文本段（含 tool 截断收尾的）
  const target = S.assistant?.root ?? lastTextCol;
  if (target && thinkSeg.root.compareDocumentPosition(target) & Node.DOCUMENT_POSITION_FOLLOWING) {
    // 思考块位于目标之后（中间可隔工具卡等）→ 紧贴目标上方
    MsgsEl.insertBefore(thinkSeg.root, target);
  }
  thinkSeg.text += delta || '';
  thinkSeg.body.textContent = thinkSeg.text === '' ? '思考中…' : thinkSeg.text;
  autoscroll();
  railSync();
}

// ---- 信息块（context/status 类事件：注入、lagged、error 提示等） ------------------

/** 渲染一条可见信息块（按序出现在流中；样式与普通消息区分：左侧色条 + 浅色底）。 */
export function renderInfoBlock(text: string, cls?: 'err' | 'warn'): void {
  if (!text) return;
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg info' + (cls ? ' ' + cls : ''));
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '系统'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble info-bubble');
  const body = el('div', 'content info-content');
  body.textContent = text;
  bubble.appendChild(body);
  msg.appendChild(bubble);
  col.appendChild(msg);
  MsgsEl.appendChild(col);
  autoscroll(true);
}

// ---- message builders ----------------------------------------------------------

export function addUserMessage(text: string, container: HTMLElement = MsgsEl): void {
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg user');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', '你'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble');
  const body = el('div', 'content');
  body.textContent = text;
  body.style.whiteSpace = 'pre-wrap';
  bubble.appendChild(body);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
  railAdd(col, 'user');
  railSync();
  autoscroll(true);
}

/** 获取当前文本段视图或创建新的流式文本气泡（连续流中的一段；container 用于离屏构建）。 */
export function ensureAssistant(container: HTMLElement = MsgsEl): AssistantView {
  if (S.assistant) return S.assistant;
  hideEmptyHint();
  const col = el('div', 'mcol');
  const msg = el('div', 'msg assistant');
  const cap = el('div', 'msg-caption');
  cap.appendChild(el('span', 'who', 'Studio'));
  cap.appendChild(el('span', null, fmtNow()));
  msg.appendChild(cap);
  const bubble = el('div', 'bubble streaming');
  const content = el('div', 'content');
  bubble.appendChild(content);
  msg.appendChild(bubble);
  col.appendChild(msg);
  container.appendChild(col);
  railAdd(col, 'assistant');
  railSync();

  // think/cards 字段为类型兼容保留（不挂载；thinking/工具卡均独立成段）
  const view: AssistantView = {
    root: msg,
    bubble,
    think: document.createElement('details'),
    thinkBody: document.createElement('div'),
    thinkTime: document.createElement('span'),
    cards: document.createElement('div'),
    content,
    text: '',
    thinkText: '',
    ops: new Map(),
    steps: 0,
  };
  lastTextCol = col; // 同轮最近文本段（thinking 重排锚点）
  S.assistant = view;
  autoscroll(true);
  return view;
}

/** 文本段收尾（turn 结束 / done 冲刷）。 */
export function finalizeAssistant(view: AssistantView): void {
  view.bubble.classList.remove('streaming');
  view.bubble.classList.add('complete');
  flushTextView(view);
  autoscroll(true);
}

// ============================================================================
// utils/markdown.ts — 增量流式 markdown 渲染（W301）
//
// 现状问题（messages.ts 旧实现）：每个渲染节拍对「整段累积文本」全量
//   marked.parse + 全量代码高亮。实测 128K 字符时单次 ≈ 60ms（不含 DOM
//   解析/布局/绘制/强制回流），60ms 节拍被吃满 → 主线程饱和、UI 假死。
//
// 本模块把文本切成两段：
//   - stableHtml：已固化前缀的 HTML（只解析一次，之后永不重解析）
//   - stableLen ：该前缀在原文中的长度
//   - tail      ：未固化尾部（每个节拍只解析这一段）
// update(fullText) 返回 stableHtml + md(tail)，在「安全切分」前提下与
// 「整段一次解析」的 HTML 逐字节等价（bench 用逐字符前缀校验实测）。
//
// 切分必须保守：宁可少固化（退化为当前全量行为，不得比现状更差），
// 也绝不固化错。判定见 findFixLen() / boundarySafe()：
//   1) 只在「空行边界」后固化完整区域（围栏内/HTML 容器块内的空行不算边界）；
//   2) 区域内未闭合围栏、未闭合 HTML 容器（pre/script/style/textarea/注释）
//      不固化；
//   3) 区域内行内标记未闭合（** / ` / ~~ / 方括号）不固化；
//   4) 引用式链接（[x] / [x][y]）的解析依赖「全文任意位置」的引用定义行，
//      而定义常出现在文末：无定义时用法只是字面量 → 允许**临时固化**（记录
//      refFrozen），一旦后续真的出现定义行则 reset() 整体重渲染一次，此后
//      含用法的区域一律不固化（详见 MarkdownStream.update）；
//   5) 区域末行含 `|` 且后一行也含 `|`（可能组成表格）时不固化；
//   6) 区域含列表项且后一行是列表项/列表残行（`1`、`1.`、`-`）时不固化
//      （会被合并成同一个列表，松散化 → <p> 包裹）；
//   7) 后一行以缩进开头（列表/引用/缩进代码可跨空行续接）、或区域末尾之后
//      没有非空行时不固化。
//   边界不安全时**不立即停止**，而是把后续块并入候选区域继续找下一个边界
//   ——避免「一个表格/一次未闭合行内标记把后续全部文本永久留在 tail 里」。
//
// 对外接口：update() 返回完整 HTML（兼容基准/历史路径）；updateParts() 额外返回
//   「本次新固化的 HTML 增量」与「尾部 HTML」，供 messages.ts 做局部 DOM 替换
//   （已固化块对应的 DOM 节点原地保留 → 浏览器不重解析、已高亮代码块不重建）。
//
// 另一个必须处理的坑：marked 的标题 id 由 Parser 内的 Slugger 递增（同名标题
//   会得到 `标题`、`标题-1`…）。若分块解析时每块用新 Parser，重复标题的 id 会
//   漂移。因此这里始终自己 new Parser 并维护跨块 slugger 状态：固化块渲染后
//   持久化 seen，尾部块渲染时以 seen 为种子但不回写（尾部每 tick 重解析，
//   回写会造成重复计数）。标题 id 因此与「整段一次解析」完全一致。
// ============================================================================
import { marked, Parser } from 'marked';

// 与现状一致（breaks/gfm）；renderMarkdown 与分块解析共用同一套默认选项
marked.setOptions({ breaks: true, gfm: true });

// ---- 兜底转义（与 utils/dom.esc 同一映射；本地实现以免本模块依赖 DOM） -------
const ESC_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ESC_MAP[c] ?? c);
}

/**
 * 用自带 slugger 状态的 Parser 渲染（等价于 marked.parse，但标题 id 计数器
 * 跨块连续）。seen 为标题 slug 计数表；persist=true 时把本次计数回写。
 */
function parseWith(seen: Record<string, number>, text: string, persist: boolean): string {
  // 复制默认选项（与 marked.parse 一致）：Parser 构造器会往 options 上写
  // renderer，直接传 marked.defaults 会污染全局默认值。
  const opts = { ...marked.defaults };
  const parser = new Parser(opts);
  Object.assign(parser.slugger.seen, seen);
  const html = parser.parse(marked.lexer(text, opts));
  if (persist) Object.assign(seen, parser.slugger.seen);
  return html;
}

/** 一次性全量渲染（历史恢复路径 / done 全文覆盖用）。 */
export function renderMarkdown(text: string): string {
  try {
    return marked.parse(text, { async: false }) as string;
  } catch {
    return '<pre>' + escapeHtml(text) + '</pre>';
  }
}

/** 单块解析（与 renderMarkdown 同管线；固化块/尾部块解析用）。 */
function md(text: string, seen: Record<string, number>, persist: boolean): string {
  try {
    return parseWith(seen, text, persist);
  } catch {
    return '<pre>' + escapeHtml(text) + '</pre>';
  }
}

// ---- 行级扫描 ----------------------------------------------------------------

/**
 * 围栏开行：与 marked 的 fences 规则同口径——反引号围栏的语言行不得含反引号
 * （marked: `` `{3,}(?=[^`\n]*(?:\n|$)) ``），波浪号围栏语言行不限。
 * 判定必须与 marked 一致：把真围栏误判为普通行会导致在代码块中间固化。
 */
const FENCE_OPEN_RE = /^ {0,3}(`{3,}(?=[^`\n]*$)|~{3,})([^\n]*)$/;
/**
 * 可能的围栏行（开或闭）：前导同字符 run + 允许的尾随 `~`/`` ` ``。
 * 与 marked 的 fences 规则同口径——闭围栏必须是**同一字符**且长度不短于开行
 * （marked: `(?: {0,3}\1[~`]* *(?=\n|$)|$)`）；若把混字符行当闭行（例如
 * 开行 ``` 而 `~~~` 之类的行），会误在代码块中间固化。
 */
const FENCE_LINE_RE = /^ {0,3}(`+|~+)([~`]*)[ \t]*$/;
/** 列表项行（无序 / 有序）。 */
const LIST_RE = /^ {0,3}(?:[-*+]|\d{1,9}[.)])(?:[ \t]|$)/;
/** 「可能是列表项」的残行（`1`、`1.`、`- `、`*`）：下一 tick 补全后会与前一块合并。 */
const LISTISH_RE = /^ {0,3}(?:[-*+]|\d{1,9})(?:[.)][ \t]*)?$/;
/** 任意缩进深度的列表项行（嵌套列表末行也会与后续同级项合并）。 */
const LIST_ANY_RE = /^[ \t]*(?:[-*+]|\d{1,9}[.)])(?:[ \t]|$)/;
/** 缩进行（2 空格以上或制表符）：列表/引用续行、缩进代码块可跨空行。 */
const INDENT_RE = /^(?: {2,}|\t)/;
/** setext 标题下划线（空行理论上阻断，保守起见仍不固化）。 */
const SETEXT_RE = /^ {0,3}(?:=+|-+)[ \t]*$/;
/** 主题分隔线（`***` 等，行内标记统计前剔除，避免误判未闭合 `**`）。 */
const THEMATIC_RE = /^ {0,3}(?:(?:\*[ \t]*){3,}|(?:-[ \t]*){3,}|(?:_[ \t]*){3,})$/;
/** 引用定义行：`[id]: url`（可出现在文末，改变前文引用式链接的解析结果）。 */
const REF_DEF_RE = /^ {0,3}\[[^\]\n]+\]:/m;
/** 引用式链接用法：`[text]` 或 `[text][ref]`（未紧跟 `(` 即非行内链接）。 */
const REF_USE_RE = /\[[^\]\n]*\](?!\()/;
/**
 * 裸 HTML 标签/构造（行内或块级）探测：`<tag`、`</tag>`、`<!--`、`<?`、`<!X`。
 *
 * marked 对 HTML 有多套跨空行吞并规则（容器块 <pre|script|style|textarea>、
 * 注释/PI/CDATA/声明、type 6/7 标签块、行内 raw block 状态），其边界行为依赖
 * 全文结构，无法用廉价的行级统计可靠判定「切分后等价」。因此采取保守策略：
 * 区域内（围栏/缩进代码之外）出现任何裸 HTML 构造 → 该区域不固化，退化为
 * 全量渲染（与现状相同，绝不比现状更差）。围栏/缩进代码里的 `<` 是字面量，
 * 不触发该规则（rust 泛型等不受影响）。
 */
const RAW_HTML_RE = /<[a-zA-Z!/?]/;
/** 缩进代码行 / 制表符起始行。 */
const CODE_LINE_RE = /^(?: {4,}|\t)/;

/**
 * 取 i 处的行内容与下一行起点。CRLF / CR / LF 均视为换行——marked 的 Lexer
 * 会先把 `\r\n|\r` 归一化为 `\n`，若这里只按 `\n` 切行，含 `\r` 的文本会
 * 与 marked 看到的分块结构不一致（可能把围栏行误判为普通行）。
 */
function lineAt(text: string, i: number): { line: string; next: number; eol: boolean } {
  let j = i;
  while (j < text.length && text[j] !== '\n' && text[j] !== '\r') j += 1;
  if (j >= text.length) return { line: text.slice(i), next: text.length, eol: false };
  let next = j + 1;
  if (text[j] === '\r' && text[next] === '\n') next += 1;
  return { line: text.slice(i, j), next, eol: true };
}

// ---- 候选区域状态（增量累加，不重复扫旧行） ------------------------------------

/** 区域 [stable, 候选边界) 的结构统计，用于判定该切分点是否与整段解析等价。 */
interface RegionState {
  inFence: boolean;        // 是否位于未闭合围栏内
  fenceChar: string;       // 围栏字符（` 或 ~）
  fenceLen: number;        // 围栏长度
  ticks: number;           // 行内代码标记（` 串）计数
  strong: number;          // ** 计数
  strike: number;          // ~~ 计数
  openBrackets: number;    // [ 计数
  closeBrackets: number;   // ] 计数
  refUse: boolean;         // 出现引用式链接用法
  hasList: boolean;        // 出现列表项（含嵌套）
  hasRawHtml: boolean;     // 区域内出现裸 HTML 标签/构造（保守：不固化）
  lastLine: string | null; // 最后一个非空行（含缩进行）
  hasContent: boolean;     // 区域内是否有非空内容
}

function newRegion(): RegionState {
  return {
    inFence: false,
    fenceChar: '',
    fenceLen: 0,
    ticks: 0,
    strong: 0,
    strike: 0,
    openBrackets: 0,
    closeBrackets: 0,
    refUse: false,
    hasList: false,
    hasRawHtml: false,
    lastLine: null,
    hasContent: false,
  };
}

function cloneRegion(st: RegionState): RegionState {
  return { ...st };
}

/** 把一行计入区域状态（围栏行只切围栏状态，不参与行内标记统计）。 */
function feedLine(st: RegionState, line: string): void {
  if (!st.inFence) {
    const fm = FENCE_OPEN_RE.exec(line);
    if (fm) {
      const marker = fm[1] ?? '';
      st.inFence = true;
      st.fenceChar = marker.charAt(0);
      st.fenceLen = marker.length;
      if (line.trim() !== '') st.hasContent = true;
      return; // 围栏开行不参与行内统计，也不作为表格候选行
    }
  } else {
    // 围栏内容行：字面量，全部跳过；只等与开行同字符且不短于开行的闭行
    const cm = FENCE_LINE_RE.exec(line);
    const marker = cm?.[1] ?? '';
    if (marker !== '' && marker.charAt(0) === st.fenceChar && marker.length >= st.fenceLen) {
      st.inFence = false;
      st.fenceChar = '';
      st.fenceLen = 0;
    }
    if (line.trim() !== '') st.hasContent = true;
    return;
  }
  if (line.trim() === '') return;
  st.hasContent = true;
  st.lastLine = line;
  // 缩进代码：其中的标记是字面量，不参与行内配对
  if (CODE_LINE_RE.test(line)) return;
  // 主题分隔线：`***` / `---` 是分隔线而非未闭合强调
  if (THEMATIC_RE.test(line)) return;
  if (RAW_HTML_RE.test(line)) st.hasRawHtml = true;
  const ticks = line.match(/`+/g);
  if (ticks) st.ticks += ticks.length;
  const strong = line.match(/\*\*/g);
  if (strong) st.strong += strong.length;
  const strike = line.match(/~~/g);
  if (strike) st.strike += strike.length;
  const open = line.match(/\[/g);
  if (open) st.openBrackets += open.length;
  const close = line.match(/\]/g);
  if (close) st.closeBrackets += close.length;
  if (REF_USE_RE.test(line)) st.refUse = true;
  if (LIST_ANY_RE.test(line)) st.hasList = true;
}

/**
 * 候选区域 [stable, boundary) 是否可在 boundary 处固化（nextLine = 边界之后
 * 第一条非空行；hasRefDef = 当前全文里已出现引用定义行）。
 */
function boundarySafe(snap: RegionState, nextLine: string, hasRefDef: boolean): boolean {
  if (snap.inFence) return false;                              // 未闭合围栏
  if (snap.hasRawHtml) return false;                           // 区域含裸 HTML（保守：不固化）
  if (snap.refUse && hasRefDef) return false;
  if (snap.ticks % 2 !== 0) return false;                      // 未闭合 `
  if (snap.strong % 2 !== 0) return false;                     // 未闭合 **
  if (snap.strike % 2 !== 0) return false;                     // 未闭合 ~~
  if (snap.openBrackets !== snap.closeBrackets) return false;  // 未闭合 [
  const last = snap.lastLine;
  // 表格：末行含 `|` 且后一行也含 `|`（可能是表头 + 分隔行/数据行）
  if (last !== null && last.indexOf('|') !== -1 && nextLine.indexOf('|') !== -1) return false;
  // 列表合并：区域内有列表项且后一行是列表项/列表残行
  if (snap.hasList && (LIST_RE.test(nextLine) || LISTISH_RE.test(nextLine))) return false;
  // 续接：后一行以缩进开头（列表/引用/缩进代码）、或为 setext 下划线
  if (INDENT_RE.test(nextLine)) return false;
  if (SETEXT_RE.test(nextLine)) return false;
  return true;
}

/**
 * 在 tail 中寻找可安全固化的前缀长度（0 = 不前进，退化为全量行为）。
 * 单次 O(n) 前向扫描：区域状态增量累加，遇到空行时挂起候选边界并快照状态，
 * 到「下一条非空行」时判定快照是否安全；不安全则作废候选、区域继续增长。
 */
function findFixLen(tail: string): number {
  // 引用定义可出现在任意位置：整段里若存在定义行，其之前的边界一律不安全
  const defIdx = tail.search(REF_DEF_RE);
  let stable = 0;              // 已确认可固化的长度
  let st = newRegion();        // 当前区域 [stable, 扫描位置)
  let pending = -1;            // 挂起的候选边界（区域结束位置）
  let snap: RegionState | null = null;
  let i = 0;
  while (i < tail.length) {
    const { line, next, eol } = lineAt(tail, i);
    // 只把「真正空行」（长度为 0）当边界：只含空白的行可被 marked 的
    // setext 标题规则跨行吞并（`(?:.|\n(?!\n))+?` 允许 ` \n`），
    // 若在空白行处固化会与整段解析结果不一致。
    const blank = eol && line === '';
    if (!blank && line.trim() !== '') {
      // 非空行：先判定挂起候选（该行属于下一个区域，故先判定再计入）
      if (pending >= 0 && snap !== null) {
        if (boundarySafe(snap, line, defIdx !== -1)) {
          stable = pending;
          st = newRegion();
        }
        pending = -1;
        snap = null;
      }
    }
    feedLine(st, line);
    if (!st.inFence && blank) {
      if (!st.hasContent) {
        // 连续空行：直接并入已固化区（无内容可解析）
        stable = next;
        st = newRegion();
        pending = -1;
        snap = null;
      } else {
        pending = next;
        snap = cloneRegion(st);
      }
    }
    i = next;
  }
  return stable;
}

// ---- 增量流式解析器 -----------------------------------------------------------

/** MarkdownStream.updateParts() 的返回值（增量 DOM 更新用）。 */
export interface MarkdownParts {
  /** 完整 HTML（= stableHtml + tailHtml） */
  html: string;
  /** 已固化前缀的 HTML（本 tick 不会变） */
  stableHtml: string;
  /** 本次新固化出来的 HTML 增量（空串 = 无新增固化） */
  stableDeltaHtml: string;
  /** 未固化尾部 HTML */
  tailHtml: string;
  /** 已固化前缀的原文长度 */
  stableLen: number;
  /** 本次是否发生整体重置（调用方须重建整个容器） */
  reset: boolean;
}

/**
 * 增量流式 markdown 解析器。
 * 每 tick 用「累积全文」调用 update()，返回该渲染的完整 HTML。
 */
export class MarkdownStream {
  /** 已固化前缀对应的 HTML */
  private stableHtml = '';
  /** stableHtml 对应的原文长度 */
  private stableLen = 0;
  /** 上一次 update() 传入的全文（用于前缀/回退判定与无变化短路） */
  private raw = '';
  /** 上一次的完整 HTML（内容未变时直接返回） */
  private html = '';
  /** 上一次的尾部 HTML（未固化部分） */
  private tailHtml = '';
  /** 已固化前缀的标题 slug 计数（跨块连续，见文件头说明） */
  private seen: Record<string, number> = {};
  /** 已固化前缀里含「无定义时的引用式链接用法」→ 定义行一旦出现必须整体重渲染 */
  private refFrozen = false;

  /** 已固化前缀长度（诊断/基准用；只读）。 */
  get stableLength(): number {
    return this.stableLen;
  }

  /** 会话清空 / 新段开始时复位缓存。 */
  reset(): void {
    this.stableHtml = '';
    this.stableLen = 0;
    this.raw = '';
    this.html = '';
    this.tailHtml = '';
    this.seen = {};
    this.refFrozen = false;
  }

  /** 每 tick 用「累积全文」调用；返回该渲染的完整 HTML。 */
  update(fullText: string): string {
    return this.updateParts(fullText).html;
  }

  /**
   * 每 tick 用「累积全文」调用；返回渲染结果的分解形式：
   *   html            = stableHtml + tailHtml（完整 HTML）
   *   stableDeltaHtml = 本次新固化出来的 HTML（空串 = 无新增固化）
   *   tailHtml        = 未固化尾部 HTML（每 tick 重建）
   *   stableLen       = 已固化前缀的原文长度
   *   reset           = 本次发生了整体重置（调用方须重建整个容器）
   */
  updateParts(fullText: string): MarkdownParts {
    const text = typeof fullText === 'string' ? fullText : String(fullText ?? '');
    if (text === this.raw) {
      // 内容未变：不重复解析，直接复用上次结果
      return {
        html: this.html,
        stableHtml: this.stableHtml,
        stableDeltaHtml: '',
        tailHtml: this.tailHtml,
        stableLen: this.stableLen,
        reset: false,
      };
    }
    let didReset = false;
    // 长度回退 / 内容不一致（done 全文覆盖、会话切换、编辑）→ 整体重来
    if (!text.startsWith(this.raw)) {
      this.reset();
      didReset = true;
    }
    // 已固化前缀里含引用式用法、而此刻出现了引用定义行 → 用法解析结果改变，
    // 整体重渲染一次（此后含用法的区域不再固化，见 boundarySafe）。
    if (this.refFrozen && REF_DEF_RE.test(text)) {
      this.reset();
      didReset = true;
    }

    const tail = text.slice(this.stableLen);
    const fix = findFixLen(tail);
    let stableDelta = '';
    if (fix > 0) {
      const block = tail.slice(0, fix);
      stableDelta = md(block, this.seen, true);
      this.stableHtml += stableDelta;
      this.stableLen += fix;
      if (REF_USE_RE.test(block)) this.refFrozen = true;
    }

    const rest = text.slice(this.stableLen);
    this.raw = text;
    this.tailHtml = md(rest, this.seen, false);
    this.html = this.stableHtml + this.tailHtml;
    return {
      html: this.html,
      stableHtml: this.stableHtml,
      stableDeltaHtml: stableDelta,
      tailHtml: this.tailHtml,
      stableLen: this.stableLen,
      reset: didReset,
    };
  }
}

